# Generated build script
html = "<!DOCTYPE html>\n<html lang=\"tr\" class=\"dark\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>ERG\u00dcNBA\u015e KANAT - \u00c7ift Tesis \u00dcretim & Sipari\u015f Portal\u0131</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script src=\"https://unpkg.com/lucide@latest\"></script>\n    <script>\n        tailwind.config = {\n            darkMode: 'class',\n            theme: {\n                extend: {\n                    colors: {\n                        brand: {\n                            50: '#f0fdf4',\n                            500: '#22c55e',\n                            600: '#16a34a',\n                            700: '#15803d',\n                        }\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body { background-color: #090d16; color: #e2e8f0; font-family: system-ui, -apple-system, sans-serif; }\n        .glass-panel { background: rgba(15, 23, 42, 0.75); backdrop-filter: blur(12px); border: 1px solid rgba(51, 65, 85, 0.4); }\n        .tab-btn.active { background: #1e293b; color: #38bdf8; border-bottom: 2px solid #38bdf8; }\n        \n        .facility-main-btn { background: #0f172a; color: #94a3b8; border: 1px solid #334155; }\n        .facility-main-btn.active { background: linear-gradient(135deg, #0284c7, #2563eb); color: #ffffff; border-color: #38bdf8; box-shadow: 0 4px 20px rgba(2, 132, 199, 0.4); font-weight: 800; }\n        \n        .order-filter-pill.active { background: #0284c7; color: #ffffff; font-weight: 700; border-color: #38bdf8; }\n        .period-btn.active { background: #0284c7; color: #ffffff; font-weight: 700; }\n        .badge { display: inline-flex; align-items: center; padding: 0.25rem 0.625rem; border-radius: 9999px; font-size: 0.75rem; font-weight: 600; }\n        input, select, textarea { background-color: #0f172a !important; border-color: #334155 !important; color: #f8fafc !important; }\n        input:focus, select:focus, textarea:focus { border-color: #38bdf8 !important; outline: none; box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.2); }\n        ::-webkit-scrollbar { width: 6px; height: 6px; }\n        ::-webkit-scrollbar-track { background: #0b0f19; }\n        ::-webkit-scrollbar-thumb { background: #334155; border-radius: 3px; }\n        ::-webkit-scrollbar-thumb:hover { background: #475569; }\n    </style>\n</head>\n<body class=\"min-h-screen flex flex-col\">\n\n    <!-- Toast Notification -->\n    <div id=\"toast\" class=\"fixed bottom-6 right-6 z-50 transform transition-all duration-300 translate-y-20 opacity-0 pointer-events-none\">\n        <div id=\"toast-content\" class=\"flex items-center gap-3 px-5 py-3.5 rounded-xl shadow-2xl border text-sm font-medium\"></div>\n    </div>\n\n    <!-- Login Overlay -->\n    <div id=\"login-overlay\" class=\"fixed inset-0 z-50 flex items-center justify-center bg-slate-950/90 backdrop-blur-md\">\n        <div class=\"glass-panel p-8 rounded-2xl w-full max-w-md shadow-2xl border border-slate-700/60 text-center\">\n            <div class=\"inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-sky-500/10 text-sky-400 mb-4 border border-sky-500/20\">\n                <i data-lucide=\"door-closed\" class=\"w-8 h-8\"></i>\n            </div>\n            <h1 class=\"text-2xl font-bold text-white tracking-tight mb-1\">ERG\u00dcNBA\u015e KANAT PORTALI</h1>\n            <p class=\"text-xs text-slate-400 mb-6\">\u00dcst Tesis & Alt Tesis Konsolide \u00dcretim Sistemi</p>\n            \n            <form id=\"login-form\" onsubmit=\"handleLogin(event)\" class=\"space-y-4 text-left\">\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Kullan\u0131c\u0131 Ad\u0131</label>\n                    <div class=\"relative\">\n                        <i data-lucide=\"user\" class=\"w-4 h-4 absolute left-3.5 top-3 text-slate-500\"></i>\n                        <input type=\"text\" id=\"login-username\" required class=\"w-full pl-10 pr-4 py-2.5 rounded-xl border text-sm\" placeholder=\"Kullan\u0131c\u0131 ad\u0131n\u0131z\">\n                    </div>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">\u015eifre</label>\n                    <div class=\"relative\">\n                        <i data-lucide=\"lock\" class=\"w-4 h-4 absolute left-3.5 top-3 text-slate-500\"></i>\n                        <input type=\"password\" id=\"login-password\" required class=\"w-full pl-10 pr-4 py-2.5 rounded-xl border text-sm\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\">\n                    </div>\n                </div>\n                <div id=\"login-error\" class=\"hidden text-rose-400 text-xs bg-rose-950/40 p-2.5 rounded-lg border border-rose-800/40\"></div>\n                <button type=\"submit\" class=\"w-full py-3 px-4 bg-gradient-to-r from-sky-500 to-indigo-600 hover:from-sky-600 hover:to-indigo-700 text-white font-semibold rounded-xl shadow-lg shadow-sky-500/20 transition duration-200 text-sm flex items-center justify-center gap-2\">\n                    <span>Giri\u015f Yap</span>\n                    <i data-lucide=\"arrow-right\" class=\"w-4 h-4\"></i>\n                </button>\n            </form>\n            <div class=\"mt-6 pt-4 border-t border-slate-800/80 text-xs text-slate-500\">\n                Varsay\u0131lan Admin: <span class=\"text-slate-400 font-mono\">admin / ergunbas2026</span>\n            </div>\n        </div>\n    </div>\n\n    <!-- Main Navigation Bar -->\n    <header class=\"sticky top-0 z-40 glass-panel border-b border-slate-800 bg-slate-950/90\">\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n            <div class=\"flex items-center justify-between h-16\">\n                <!-- Brand / Logo -->\n                <div class=\"flex items-center gap-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-sky-500 to-indigo-600 flex items-center justify-center text-white shadow-md shadow-sky-500/20\">\n                        <i data-lucide=\"layers\" class=\"w-5 h-5\"></i>\n                    </div>\n                    <div>\n                        <div class=\"font-bold text-base tracking-tight text-white flex items-center gap-2\">\n                            ERG\u00dcNBA\u015e <span class=\"text-xs font-semibold px-2 py-0.5 rounded bg-sky-500/20 text-sky-400 border border-sky-500/30\">KANAT</span>\n                        </div>\n                        <div class=\"text-[10px] text-slate-400\">\u00dcst Tesis & Alt Tesis Y\u00f6netimi</div>\n                    </div>\n                </div>\n\n                <!-- Main Tabs -->\n                <nav class=\"hidden md:flex items-center gap-1\">\n                    <button onclick=\"switchTab('dashboard')\" id=\"tab-btn-dashboard\" class=\"tab-btn active px-4 py-2 text-sm font-medium text-slate-300 hover:text-white rounded-lg flex items-center gap-2 transition\">\n                        <i data-lucide=\"layout-dashboard\" class=\"w-4 h-4\"></i>\n                        <span>Dashboard & \u00d6zetler</span>\n                    </button>\n                    <button onclick=\"switchTab('orders')\" id=\"tab-btn-orders\" class=\"tab-btn px-4 py-2 text-sm font-medium text-slate-300 hover:text-white rounded-lg flex items-center gap-2 transition\">\n                        <i data-lucide=\"package\" class=\"w-4 h-4\"></i>\n                        <span>Sipari\u015fler</span>\n                    </button>\n                    <button onclick=\"switchTab('daily')\" id=\"tab-btn-daily\" class=\"tab-btn px-4 py-2 text-sm font-medium text-slate-300 hover:text-white rounded-lg flex items-center gap-2 transition\">\n                        <i data-lucide=\"calendar-plus\" class=\"w-4 h-4\"></i>\n                        <span>G\u00fcnl\u00fck Giri\u015f</span>\n                    </button>\n                    <button onclick=\"switchTab('machines')\" id=\"tab-btn-machines\" class=\"tab-btn px-4 py-2 text-sm font-medium text-slate-300 hover:text-white rounded-lg flex items-center gap-2 transition\">\n                        <i data-lucide=\"cpu\" class=\"w-4 h-4\"></i>\n                        <span>Makineler</span>\n                    </button>\n                    <button onclick=\"switchTab('users')\" id=\"tab-btn-users\" class=\"tab-btn hidden px-4 py-2 text-sm font-medium text-slate-300 hover:text-white rounded-lg flex items-center gap-2 transition\">\n                        <i data-lucide=\"users\" class=\"w-4 h-4\"></i>\n                        <span>Kullan\u0131c\u0131lar</span>\n                    </button>\n                </nav>\n\n                <!-- User Profile & Edit Names -->\n                <div class=\"flex items-center gap-3\">\n                    <button onclick=\"openFacilityModal()\" title=\"Tesis \u0130simlerini De\u011fi\u015ftir\" class=\"hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-slate-900 hover:bg-slate-800 border border-slate-700 text-xs font-semibold text-slate-300 hover:text-sky-400 transition\">\n                        <i data-lucide=\"settings-2\" class=\"w-3.5 h-3.5\"></i>\n                        <span>Tesis \u0130simleri</span>\n                    </button>\n                    <div class=\"flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-900 border border-slate-800\">\n                        <div class=\"w-2 h-2 rounded-full bg-emerald-400 animate-pulse\"></div>\n                        <span id=\"user-display-name\" class=\"text-xs font-semibold text-slate-200\">Admin</span>\n                    </div>\n                    <button onclick=\"handleLogout()\" title=\"\u00c7\u0131k\u0131\u015f Yap\" class=\"p-2 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-rose-400 transition\">\n                        <i data-lucide=\"log-out\" class=\"w-4 h-4\"></i>\n                    </button>\n                </div>\n            </div>\n        </div>\n    </header>\n\n    <!-- App Content Area -->\n    <main class=\"flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6\">\n\n        <!-- ============================================================== -->\n        <!-- B\u00dcY\u00dcK VE NET TES\u0130S AYIRMA SEKME BAR'I (HER YERDEN ER\u0130\u015e\u0130LEB\u0130L\u0130R) -->\n        <!-- ============================================================== -->\n        <div class=\"glass-panel p-2.5 rounded-2xl border border-slate-800 shadow-2xl\">\n            <div class=\"flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3\">\n                \n                <!-- Facility Switch Buttons (CLICKING OPENS THOSE ORDERS DIRECTLY) -->\n                <div class=\"flex items-center gap-2 flex-1\">\n                    <button type=\"button\" onclick=\"goToFacilityOrders('all')\" id=\"fac-btn-all\" class=\"facility-main-btn active flex-1 py-3.5 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition hover:border-sky-500\">\n                        <i data-lucide=\"building-2\" class=\"w-4 h-4\"></i>\n                        <span>\ud83c\udfe2 T\u00dcM S\u0130PAR\u0130\u015eLER (243 Adet)</span>\n                    </button>\n                    <button type=\"button\" onclick=\"goToFacilityOrders('fac1')\" id=\"fac-btn-fac1\" class=\"facility-main-btn flex-1 py-3.5 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition hover:border-sky-400\">\n                        <i data-lucide=\"factory\" class=\"w-4 h-4 text-sky-400\"></i>\n                        <span id=\"fac1-main-btn-text\">\ud83c\udfed \u00dcST TES\u0130S (207 Sipari\u015f)</span>\n                    </button>\n                    <button type=\"button\" onclick=\"goToFacilityOrders('fac2')\" id=\"fac-btn-fac2\" class=\"facility-main-btn flex-1 py-3.5 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition hover:border-indigo-400\">\n                        <i data-lucide=\"factory\" class=\"w-4 h-4 text-indigo-400\"></i>\n                        <span id=\"fac2-main-btn-text\">\ud83c\udfed ALT TES\u0130S (36 Sipari\u015f)</span>\n                    </button>\n                </div>\n\n                <!-- Quick Period Selector & Month Selector -->\n                <div class=\"flex items-center gap-2 justify-end\">\n                    <div class=\"flex rounded-xl bg-slate-900 p-1 border border-slate-800\">\n                        <button type=\"button\" onclick=\"setPeriod('daily')\" id=\"period-btn-daily\" class=\"period-btn px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-300 hover:text-white transition\">\u2600\ufe0f G\u00fcnl\u00fck</button>\n                        <button type=\"button\" onclick=\"setPeriod('weekly')\" id=\"period-btn-weekly\" class=\"period-btn active px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-300 hover:text-white transition\">\ud83d\udcc5 Bu Hafta</button>\n                        <button type=\"button\" onclick=\"setPeriod('monthly')\" id=\"period-btn-monthly\" class=\"period-btn px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-300 hover:text-white transition\">\ud83d\uddd3\ufe0f Bu Ay</button>\n                    </div>\n                    <input type=\"month\" id=\"global-month-picker\" onchange=\"handleGlobalMonthChange()\" class=\"px-2.5 py-1.5 rounded-xl border text-xs font-semibold text-white\">\n                </div>\n            </div>\n        </div>\n\n        <!-- ============================================================== -->\n        <!-- TAB 1: DASHBOARD, \u00d6ZETLER & SARKAN S\u0130PAR\u0130\u015eLER -->\n        <!-- ============================================================== -->\n        <section id=\"tab-dashboard\" class=\"space-y-6\">\n\n            <!-- KONSOL\u0130DE / SE\u00c7\u0130L\u0130 TES\u0130S KAPI TOPLAM KARTI -->\n            <div class=\"glass-panel p-6 rounded-2xl border border-sky-500/30 bg-gradient-to-br from-slate-900 via-sky-950/20 to-slate-900\">\n                <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 border-b border-slate-800/80 pb-4 mb-4\">\n                    <div>\n                        <div class=\"text-xs font-bold uppercase tracking-wider text-sky-400 flex items-center gap-2\">\n                            <i data-lucide=\"check-circle-2\" class=\"w-4 h-4\"></i>\n                            <span id=\"dash-period-title\">Bu Hafta \u00c7\u0131kan Toplam Kap\u0131</span>\n                        </div>\n                        <div class=\"text-3xl sm:text-4xl font-extrabold text-white mt-1\" id=\"dash-consolidated-total\">0 <span class=\"text-base font-normal text-slate-400\">kap\u0131</span></div>\n                    </div>\n                    \n                    <!-- Both Facilities Breakdown Cards (Clicking switches to those orders directly) -->\n                    <div class=\"grid grid-cols-2 gap-3 w-full sm:w-auto\">\n                        <div onclick=\"goToFacilityOrders('fac1')\" class=\"cursor-pointer p-3.5 rounded-xl bg-slate-900/90 border border-sky-500/40 hover:border-sky-400 hover:bg-slate-850 text-slate-300 transition group\">\n                            <div class=\"text-[11px] text-sky-400 uppercase font-bold flex items-center justify-between\">\n                                <span class=\"flex items-center gap-1.5\"><i data-lucide=\"factory\" class=\"w-3.5 h-3.5\"></i> <span id=\"fac1-label-name\">\u00dcst Tesis (207)</span></span>\n                                <span class=\"text-[10px] text-sky-300 opacity-0 group-hover:opacity-100 transition\">Sipari\u015fleri A\u00e7 \u2192</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold text-white mt-1\" id=\"dash-fac1-output\">0 <span class=\"text-xs font-normal text-slate-400\">kap\u0131</span></div>\n                            <div class=\"text-[10px] text-slate-400 mt-1\">207 Sipari\u015f \u2022 <strong class=\"text-slate-200\">6.223 Kap\u0131</strong></div>\n                        </div>\n                        \n                        <div onclick=\"goToFacilityOrders('fac2')\" class=\"cursor-pointer p-3.5 rounded-xl bg-slate-900/90 border border-indigo-500/40 hover:border-indigo-400 hover:bg-slate-850 text-slate-300 transition group\">\n                            <div class=\"text-[11px] text-indigo-400 uppercase font-bold flex items-center justify-between\">\n                                <span class=\"flex items-center gap-1.5\"><i data-lucide=\"factory\" class=\"w-3.5 h-3.5\"></i> <span id=\"fac2-label-name\">Alt Tesis (36)</span></span>\n                                <span class=\"text-[10px] text-indigo-300 opacity-0 group-hover:opacity-100 transition\">Sipari\u015fleri A\u00e7 \u2192</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold text-white mt-1\" id=\"dash-fac2-output\">0 <span class=\"text-xs font-normal text-slate-400\">kap\u0131</span></div>\n                            <div class=\"text-[10px] text-slate-400 mt-1\">36 Sipari\u015f \u2022 <strong class=\"text-slate-200\">11.259 Kap\u0131</strong></div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs text-slate-400\">\n                    <div class=\"flex items-center gap-2\">\n                        <i data-lucide=\"calendar\" class=\"w-4 h-4 text-slate-500\"></i>\n                        <span>D\u00f6nem: <strong class=\"text-slate-200\" id=\"dash-period-range\">--</strong></span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <i data-lucide=\"building\" class=\"w-4 h-4 text-slate-500\"></i>\n                        <span>G\u00f6r\u00fcnt\u00fclenen: <strong class=\"text-sky-300 font-bold\" id=\"dash-selected-facility-label\">T\u00fcm Tesisler</strong></span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <i data-lucide=\"clock\" class=\"w-4 h-4 text-slate-500\"></i>\n                        <span>Ay: <strong class=\"text-slate-200\" id=\"dash-auto-month-label\">--</strong></span>\n                    </div>\n                </div>\n            </div>\n\n            <!-- SARKAN & GEC\u0130KEN S\u0130PAR\u0130\u015eLER \u00d6ZEL TAK\u0130P PANEL\u0130 -->\n            <div class=\"glass-panel p-6 rounded-2xl border border-rose-950/60 bg-gradient-to-br from-slate-900/90 to-rose-950/20\">\n                <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 mb-4\">\n                    <div>\n                        <h2 class=\"text-base font-bold text-rose-300 flex items-center gap-2\">\n                            <i data-lucide=\"alert-triangle\" class=\"w-5 h-5 text-rose-400\"></i>\n                            Sarkan ve Bu Hafta Yeti\u015fmesi Gereken Sipari\u015fler\n                        </h2>\n                        <p class=\"text-xs text-slate-400\">Teslim tarihi ge\u00e7mi\u015f veya bu hafta teslim edilmesi gereken a\u00e7\u0131k sipari\u015flerin durumu</p>\n                    </div>\n                    <span id=\"sarkan-count-badge\" class=\"badge bg-rose-500/20 text-rose-300 border border-rose-500/40\">0 Kritik Sipari\u015f</span>\n                </div>\n\n                <div class=\"overflow-x-auto rounded-xl border border-slate-800\">\n                    <table class=\"w-full text-left text-xs text-slate-300\">\n                        <thead class=\"bg-slate-900/90 uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                            <tr>\n                                <th class=\"px-4 py-3\">Sipari\u015f No</th>\n                                <th class=\"px-4 py-3\">Tesis</th>\n                                <th class=\"px-4 py-3\">M\u00fc\u015fteri</th>\n                                <th class=\"px-4 py-3\">Model</th>\n                                <th class=\"px-3 py-3 text-center\">\u0130stenen</th>\n                                <th class=\"px-3 py-3 text-center text-emerald-400 font-semibold\">\u00dcretilen</th>\n                                <th class=\"px-3 py-3 text-center text-rose-400 font-bold\">Kalan Eksik</th>\n                                <th class=\"px-3 py-3 text-center\">Teslim Tarihi</th>\n                                <th class=\"px-4 py-3 text-center\">Sarkma / Gecikme Durumu</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"sarkan-siparisler-tbody\" class=\"divide-y divide-slate-800/60\">\n                            <tr>\n                                <td colspan=\"9\" class=\"text-center py-6 text-slate-500\">Sarkan sipari\u015f bulunmuyor, t\u00fcm sipari\u015fler zaman\u0131nda! \ud83c\udf89</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n\n            <!-- HAFTALIK G\u00dcN G\u00dcN \u00dcRET\u0130M DA\u011eILIMI -->\n            <div class=\"glass-panel p-6 rounded-2xl border border-slate-800\">\n                <div class=\"flex items-center justify-between mb-4\">\n                    <div>\n                        <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\n                            <i data-lucide=\"bar-chart-3\" class=\"w-5 h-5 text-sky-400\"></i>\n                            Haftal\u0131k G\u00fcnl\u00fck \u00dcretim Da\u011f\u0131l\u0131m\u0131 (Pzt - Paz)\n                        </h2>\n                        <p class=\"text-xs text-slate-400\" id=\"weekly-date-range\">Haftal\u0131k \u00fcretim trendi</p>\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 md:grid-cols-7 gap-3\" id=\"weekly-days-cards\">\n                    <!-- Dynamic 7 days cards -->\n                </div>\n            </div>\n\n            <!-- AKT\u0130F S\u0130PAR\u0130\u015eLER\u0130N \u0130LERLEME L\u0130STES\u0130 -->\n            <div class=\"glass-panel p-6 rounded-2xl border border-slate-800\">\n                <div class=\"flex items-center justify-between mb-4\">\n                    <div>\n                        <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\n                            <i data-lucide=\"trending-up\" class=\"w-5 h-5 text-sky-400\"></i>\n                            Aktif Sipari\u015flerin \u0130lerleme Durumu\n                        </h2>\n                        <p class=\"text-xs text-slate-400\">A\u015famalardan ge\u00e7en sipari\u015flerin anl\u0131k \u00fcretim oranlar\u0131</p>\n                    </div>\n                    <button onclick=\"switchTab('orders')\" class=\"text-xs text-sky-400 hover:text-sky-300 flex items-center gap-1 font-semibold\">\n                        Sipari\u015fleri Y\u00f6net <i data-lucide=\"arrow-right\" class=\"w-3.5 h-3.5\"></i>\n                    </button>\n                </div>\n                <div id=\"dash-orders-list\" class=\"space-y-3\">\n                    <div class=\"text-center py-8 text-slate-500 text-sm\">Y\u00fckleniyor...</div>\n                </div>\n            </div>\n\n            <!-- \u0130ki S\u00fctun: A\u015fama \u00dcretim Hacmi & Makine S\u0131ralamas\u0131 -->\n            <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n                <!-- A\u015fama \u00dcretim Hacmi -->\n                <div class=\"glass-panel p-6 rounded-2xl border border-slate-800\">\n                    <h3 class=\"text-base font-bold text-white mb-1 flex items-center gap-2\">\n                        <i data-lucide=\"layers\" class=\"w-4 h-4 text-sky-400\"></i>\n                        A\u015fama Bazl\u0131 \u00dcretim Da\u011f\u0131l\u0131m\u0131\n                    </h3>\n                    <p class=\"text-xs text-slate-400 mb-4\">A\u015famalarda \u00fcretilen toplam adetler</p>\n                    <div id=\"dash-stage-stats\" class=\"space-y-2.5\">\n                        <div class=\"text-xs text-slate-500 py-4 text-center\">Veri bulunmuyor</div>\n                    </div>\n                </div>\n\n                <!-- Makine S\u0131ralamas\u0131 -->\n                <div class=\"glass-panel p-6 rounded-2xl border border-slate-800\">\n                    <h3 class=\"text-base font-bold text-white mb-1 flex items-center gap-2\">\n                        <i data-lucide=\"cpu\" class=\"w-4 h-4 text-emerald-400\"></i>\n                        Makine Bazl\u0131 \u00dcretim S\u0131ralamas\u0131\n                    </h3>\n                    <p class=\"text-xs text-slate-400 mb-4\">En y\u00fcksek hacim \u00fcreten makineler/tezgahlar</p>\n                    <div id=\"dash-machine-stats\" class=\"space-y-2.5\">\n                        <div class=\"text-xs text-slate-500 py-4 text-center\">Veri bulunmuyor</div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- TAB 2: S\u0130PAR\u0130\u015eLER (ORDERS) -->\n        <!-- ============================================================== -->\n        <section id=\"tab-orders\" class=\"hidden space-y-6\">\n            <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n                <div>\n                    <h2 class=\"text-xl font-bold text-white flex items-center gap-2\">\n                        <i data-lucide=\"package\" class=\"w-5 h-5 text-sky-400\"></i>\n                        Sipari\u015f Y\u00f6netimi\n                    </h2>\n                    <p class=\"text-xs text-slate-400\" id=\"orders-subtitle-text\">Tesis bazl\u0131 sipari\u015f listesi</p>\n                </div>\n                \n                <div class=\"flex items-center gap-3\">\n                    <button onclick=\"openOrderModal()\" class=\"px-4 py-2.5 bg-sky-500 hover:bg-sky-600 text-white font-semibold rounded-xl text-sm shadow-lg shadow-sky-500/20 flex items-center gap-2 transition\">\n                        <i data-lucide=\"plus-circle\" class=\"w-4 h-4\"></i>\n                        Yeni Sipari\u015f Ekle\n                    </button>\n                </div>\n            </div>\n\n            <!-- Quick Sub-Filter Pills inside Orders Tab -->\n            <div class=\"flex flex-wrap items-center justify-between gap-3 p-3 rounded-2xl bg-slate-900 border border-slate-800\">\n                <div class=\"flex items-center gap-2\">\n                    <button onclick=\"selectFacility('all')\" id=\"order-pill-all\" class=\"order-filter-pill active px-4 py-2 rounded-xl border border-slate-700 text-xs font-bold transition\">\n                        \ud83c\udfe2 T\u00dcM\u00dc (<span id=\"count-all-orders\">243</span>)\n                    </button>\n                    <button onclick=\"selectFacility('fac1')\" id=\"order-pill-fac1\" class=\"order-filter-pill px-4 py-2 rounded-xl border border-slate-700 text-xs font-bold text-sky-400 transition\">\n                        \ud83c\udfed \u00dcST TES\u0130S (<span id=\"count-fac1-orders\">207</span>)\n                    </button>\n                    <button onclick=\"selectFacility('fac2')\" id=\"order-pill-fac2\" class=\"order-filter-pill px-4 py-2 rounded-xl border border-slate-700 text-xs font-bold text-indigo-400 transition\">\n                        \ud83c\udfed ALT TES\u0130S (<span id=\"count-fac2-orders\">36</span>)\n                    </button>\n                </div>\n                \n                <!-- Quick Search in Orders -->\n                <div class=\"relative w-full sm:w-64\">\n                    <i data-lucide=\"search\" class=\"w-4 h-4 absolute left-3 top-2.5 text-slate-500\"></i>\n                    <input type=\"text\" id=\"order-search-input\" oninput=\"filterOrdersTableBySearch()\" placeholder=\"Sipari\u015f, M\u00fc\u015fteri, Model Ara...\" class=\"w-full pl-9 pr-3 py-1.5 rounded-xl border text-xs\">\n                </div>\n            </div>\n\n            <!-- Orders Table -->\n            <div class=\"glass-panel rounded-2xl border border-slate-800 overflow-hidden\">\n                <div class=\"overflow-x-auto\">\n                    <table class=\"w-full text-left text-sm text-slate-300\">\n                        <thead class=\"bg-slate-900/80 text-xs uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                            <tr>\n                                <th class=\"px-4 py-3.5\">Sipari\u015f No</th>\n                                <th class=\"px-4 py-3.5\">Tesis</th>\n                                <th class=\"px-4 py-3.5\">M\u00fc\u015fteri</th>\n                                <th class=\"px-4 py-3.5\">Kap\u0131 Modeli</th>\n                                <th class=\"px-4 py-3.5 text-center\">Hedef Adet</th>\n                                <th class=\"px-4 py-3.5 text-center text-emerald-400 font-bold\">\u00dcretilen</th>\n                                <th class=\"px-4 py-3.5 text-center text-rose-400 font-bold\">Kalan Eksik</th>\n                                <th class=\"px-4 py-3.5\">Teslim Tarihi</th>\n                                <th class=\"px-4 py-3.5\">\u0130lerleme</th>\n                                <th class=\"px-4 py-3.5 text-center\">Durum</th>\n                                <th class=\"px-4 py-3.5 text-right\">\u0130\u015flemler</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"orders-table-body\" class=\"divide-y divide-slate-800/60\">\n                            <tr>\n                                <td colspan=\"11\" class=\"text-center py-8 text-slate-500\">Sipari\u015fler y\u00fckleniyor...</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- TAB 3: G\u00dcNL\u00dcK \u00dcRET\u0130M G\u0130R\u0130\u015e\u0130 -->\n        <!-- ============================================================== -->\n        <section id=\"tab-daily\" class=\"hidden space-y-6\">\n            <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n                <div>\n                    <h2 class=\"text-xl font-bold text-white flex items-center gap-2\">\n                        <i data-lucide=\"calendar-plus\" class=\"w-5 h-5 text-emerald-400\"></i>\n                        G\u00fcnl\u00fck A\u015fama Bazl\u0131 \u00dcretim Giri\u015fi\n                    </h2>\n                    <p class=\"text-xs text-slate-400\">Tesis, tarih, vardiya ve sipari\u015f se\u00e7erek a\u015famalarda \u00fcretilen kap\u0131 adetlerini girin</p>\n                </div>\n                <div class=\"flex items-center gap-3\">\n                    <button onclick=\"saveDailyProduction()\" class=\"px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold rounded-xl text-sm shadow-lg shadow-emerald-600/20 flex items-center gap-2 transition\">\n                        <i data-lucide=\"save\" class=\"w-4 h-4\"></i>\n                        G\u00fcn\u00fc Kaydet\n                    </button>\n                </div>\n            </div>\n\n            <!-- Big Facility Switcher in Daily Entry -->\n            <div class=\"glass-panel p-4 rounded-2xl border border-slate-800\">\n                <div class=\"text-xs font-bold text-slate-400 uppercase tracking-wider mb-2\">\u00dcretim Giri\u015fi Yap\u0131lacak Tesisi Se\u00e7in:</div>\n                <div class=\"grid grid-cols-2 gap-3\">\n                    <button type=\"button\" onclick=\"setDailyFacility('fac1')\" id=\"daily-fac-btn-fac1\" class=\"p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-sky-600 text-white border-sky-400 shadow-lg shadow-sky-600/30\">\n                        <i data-lucide=\"factory\" class=\"w-5 h-5\"></i>\n                        <span id=\"daily-fac1-text\">\ud83c\udfed \u00dcST TES\u0130S (207 Sipari\u015f)</span>\n                    </button>\n                    <button type=\"button\" onclick=\"setDailyFacility('fac2')\" id=\"daily-fac-btn-fac2\" class=\"p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-slate-900 text-slate-400 border-slate-700 hover:border-slate-500\">\n                        <i data-lucide=\"factory\" class=\"w-5 h-5\"></i>\n                        <span id=\"daily-fac2-text\">\ud83c\udfed ALT TES\u0130S (36 Sipari\u015f)</span>\n                    </button>\n                </div>\n            </div>\n\n            <!-- Filter / Shift Bar -->\n            <div class=\"glass-panel p-5 rounded-2xl border border-slate-800 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5\">Tarih</label>\n                    <input type=\"date\" id=\"daily-date-picker\" onchange=\"handleDailyDateChange()\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-medium\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5\">Vardiya</label>\n                    <select id=\"daily-shift-select\" onchange=\"handleDailyDateChange()\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-medium\">\n                        <option value=\"gunduz\">\u2600\ufe0f G\u00fcnd\u00fcz Vardiyas\u0131 (08:00 - 20:00)</option>\n                        <option value=\"gece\">\ud83c\udf19 Gece Vardiyas\u0131 (20:00 - 08:00)</option>\n                    </select>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5\">Sorumlu Operat\u00f6r</label>\n                    <select id=\"daily-operator-select\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-medium\">\n                        <option value=\"\">Operat\u00f6r Se\u00e7in...</option>\n                    </select>\n                </div>\n            </div>\n\n            <!-- Order Selection Block -->\n            <div class=\"glass-panel p-6 rounded-2xl border border-slate-800 space-y-6\">\n                <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 border-b border-slate-800/80 pb-4\">\n                    <div class=\"w-full sm:w-1/2\">\n                        <label class=\"block text-xs font-semibold text-sky-400 uppercase tracking-wider mb-1.5\">\u0130\u015flem Yap\u0131lacak Sipari\u015f</label>\n                        <select id=\"daily-order-select\" onchange=\"handleOrderSelectionForDaily()\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-semibold text-white\">\n                            <option value=\"\">Sipari\u015f Se\u00e7iniz...</option>\n                        </select>\n                    </div>\n                    <div id=\"selected-order-info-badge\" class=\"hidden text-xs px-4 py-2.5 rounded-xl bg-slate-900 border border-slate-700 text-slate-300\"></div>\n                </div>\n\n                <!-- Dynamic Stages Table for Selected Order -->\n                <div>\n                    <div class=\"flex items-center justify-between mb-3\">\n                        <h3 class=\"text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2\">\n                            <i data-lucide=\"layers\" class=\"w-4 h-4 text-sky-400\"></i>\n                            A\u015fama \u00dcretim Tablosu\n                        </h3>\n                        <span class=\"text-xs text-slate-400\">Her a\u015famada \u00fcretilen net kap\u0131/kanat adedini girin</span>\n                    </div>\n\n                    <div class=\"overflow-x-auto rounded-xl border border-slate-800\">\n                        <table class=\"w-full text-left text-sm text-slate-300\">\n                            <thead class=\"bg-slate-900/90 text-xs uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                                <tr>\n                                    <th class=\"px-4 py-3\">\u00dcretim A\u015famas\u0131</th>\n                                    <th class=\"px-4 py-3\">Kullan\u0131lan Makine / \u0130stasyon</th>\n                                    <th class=\"px-3 py-3 text-center w-36 text-emerald-400 font-bold\">\u00dcretilen Adet</th>\n                                    <th class=\"px-3 py-3 text-center w-28\">\u00c7al\u0131\u015fma S\u00fcresi (sa)</th>\n                                    <th class=\"px-4 py-3\">Notlar / A\u00e7\u0131klama</th>\n                                </tr>\n                            </thead>\n                            <tbody id=\"daily-stages-tbody\" class=\"divide-y divide-slate-800/60\">\n                                <tr>\n                                    <td colspan=\"5\" class=\"text-center py-8 text-slate-500 text-sm\">L\u00fctfen yukar\u0131dan bir sipari\u015f se\u00e7iniz.</td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- Machine Downtimes Section -->\n                <div class=\"pt-4 border-t border-slate-800/80\">\n                    <div class=\"flex items-center justify-between mb-3\">\n                        <h3 class=\"text-sm font-bold text-amber-400 uppercase tracking-wider flex items-center gap-2\">\n                            <i data-lucide=\"alert-triangle\" class=\"w-4 h-4\"></i>\n                            Makine Duru\u015f Kay\u0131tlar\u0131 (Ar\u0131za / Bak\u0131m / Ayar)\n                        </h3>\n                        <button type=\"button\" onclick=\"addDowntimeRow()\" class=\"text-xs px-3 py-1.5 rounded-lg bg-amber-500/10 text-amber-400 hover:bg-amber-500/20 border border-amber-500/30 flex items-center gap-1\">\n                            <i data-lucide=\"plus\" class=\"w-3.5 h-3.5\"></i> Duru\u015f Ekle\n                        </button>\n                    </div>\n\n                    <div class=\"overflow-x-auto rounded-xl border border-slate-800\">\n                        <table class=\"w-full text-left text-sm text-slate-300\">\n                            <thead class=\"bg-slate-900/90 text-xs uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                                <tr>\n                                    <th class=\"px-4 py-3\">Makine</th>\n                                    <th class=\"px-4 py-3\">Duru\u015f Nedeni</th>\n                                    <th class=\"px-3 py-3 text-center w-32\">S\u00fcre (Dakika)</th>\n                                    <th class=\"px-4 py-3\">A\u00e7\u0131klama</th>\n                                    <th class=\"px-3 py-3 text-right w-16\">Sil</th>\n                                </tr>\n                            </thead>\n                            <tbody id=\"daily-downtimes-tbody\" class=\"divide-y divide-slate-800/60\">\n                                <!-- Dynamic rows -->\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- TAB 4: MAK\u0130NELER (MACHINES) -->\n        <!-- ============================================================== -->\n        <section id=\"tab-machines\" class=\"hidden space-y-6\">\n            <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n                <div>\n                    <h2 class=\"text-xl font-bold text-white flex items-center gap-2\">\n                        <i data-lucide=\"cpu\" class=\"w-5 h-5 text-indigo-400\"></i>\n                        Makine ve \u0130stasyon Y\u00f6netimi\n                    </h2>\n                    <p class=\"text-xs text-slate-400\">Fabrikan\u0131zdaki makineleri ve hangi tesiste bulunduklar\u0131n\u0131 tan\u0131mlay\u0131n</p>\n                </div>\n                <button onclick=\"openMachineModal()\" class=\"px-4 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-xl text-sm shadow-lg shadow-indigo-600/20 flex items-center gap-2 transition\">\n                    <i data-lucide=\"plus-circle\" class=\"w-4 h-4\"></i>\n                    Yeni Makine Ekle\n                </button>\n            </div>\n\n            <!-- Machines Table -->\n            <div class=\"glass-panel rounded-2xl border border-slate-800 overflow-hidden\">\n                <div class=\"overflow-x-auto\">\n                    <table class=\"w-full text-left text-sm text-slate-300\">\n                        <thead class=\"bg-slate-900/80 text-xs uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                            <tr>\n                                <th class=\"px-4 py-3.5\">Makine / Hat Ad\u0131</th>\n                                <th class=\"px-4 py-3.5\">Bulundu\u011fu Tesis</th>\n                                <th class=\"px-4 py-3.5\">Ba\u011fl\u0131 Oldu\u011fu A\u015fama</th>\n                                <th class=\"px-4 py-3.5 text-center\">Kapasite (Adet/sa)</th>\n                                <th class=\"px-4 py-3.5 text-center\">Durum</th>\n                                <th class=\"px-4 py-3.5\">Notlar</th>\n                                <th class=\"px-4 py-3.5 text-right\">\u0130\u015flemler</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"machines-table-body\" class=\"divide-y divide-slate-800/60\">\n                            <tr>\n                                <td colspan=\"7\" class=\"text-center py-8 text-slate-500\">Makineler y\u00fckleniyor...</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- TAB 5: KULLANICILAR (USERS - Admin Only) -->\n        <!-- ============================================================== -->\n        <section id=\"tab-users\" class=\"hidden space-y-6\">\n            <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n                <div>\n                    <h2 class=\"text-xl font-bold text-white flex items-center gap-2\">\n                        <i data-lucide=\"users\" class=\"w-5 h-5 text-sky-400\"></i>\n                        Kullan\u0131c\u0131 & Operat\u00f6r Y\u00f6netimi\n                    </h2>\n                    <p class=\"text-xs text-slate-400\">Sisteme eri\u015febilecek y\u00f6neticileri ve operat\u00f6rleri y\u00f6netin</p>\n                </div>\n                <button onclick=\"openUserModal()\" class=\"px-4 py-2.5 bg-sky-500 hover:bg-sky-600 text-white font-semibold rounded-xl text-sm shadow-lg shadow-sky-500/20 flex items-center gap-2 transition\">\n                    <i data-lucide=\"user-plus\" class=\"w-4 h-4\"></i>\n                    Yeni Kullan\u0131c\u0131 Ekle\n                </button>\n            </div>\n\n            <!-- Users Table -->\n            <div class=\"glass-panel rounded-2xl border border-slate-800 overflow-hidden\">\n                <div class=\"overflow-x-auto\">\n                    <table class=\"w-full text-left text-sm text-slate-300\">\n                        <thead class=\"bg-slate-900/80 text-xs uppercase font-semibold text-slate-400 border-b border-slate-800\">\n                            <tr>\n                                <th class=\"px-4 py-3.5\">Ad Soyad</th>\n                                <th class=\"px-4 py-3.5\">Kullan\u0131c\u0131 Ad\u0131</th>\n                                <th class=\"px-4 py-3.5 text-center\">Rol</th>\n                                <th class=\"px-4 py-3.5 text-right\">\u0130\u015flemler</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"users-table-body\" class=\"divide-y divide-slate-800/60\">\n                            <tr>\n                                <td colspan=\"4\" class=\"text-center py-8 text-slate-500\">Kullan\u0131c\u0131lar y\u00fckleniyor...</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </section>\n\n    </main>\n\n    <!-- ============================================================== -->\n    <!-- MODALS -->\n    <!-- ============================================================== -->\n\n    <!-- Facility Names Modal -->\n    <div id=\"modal-facility\" class=\"fixed inset-0 z-50 hidden flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4\">\n        <div class=\"glass-panel p-6 sm:p-8 rounded-2xl w-full max-w-md border border-slate-700 shadow-2xl\">\n            <div class=\"flex items-center justify-between border-b border-slate-800 pb-4 mb-6\">\n                <h3 class=\"text-lg font-bold text-white flex items-center gap-2\">\n                    <i data-lucide=\"settings-2\" class=\"w-5 h-5 text-sky-400\"></i> Tesis \u0130simlerini D\u00fczenle\n                </h3>\n                <button onclick=\"closeFacilityModal()\" class=\"text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800\">\n                    <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\n                </button>\n            </div>\n\n            <form id=\"facility-form\" onsubmit=\"handleFacilitySubmit(event)\" class=\"space-y-4\">\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">1. Tesis (\u00dcst Tesis) Ad\u0131 *</label>\n                    <input type=\"text\" id=\"form-fac1-name\" required placeholder=\"\u00d6rn: \u00dcst Tesis (Ana Fabrika)\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">2. Tesis (Alt Tesis) Ad\u0131 *</label>\n                    <input type=\"text\" id=\"form-fac2-name\" required placeholder=\"\u00d6rn: Alt Tesis (2. Fabrika)\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div class=\"flex items-center justify-end gap-3 pt-4 border-t border-slate-800\">\n                    <button type=\"button\" onclick=\"closeFacilityModal()\" class=\"px-4 py-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 text-sm\">\u0130ptal</button>\n                    <button type=\"submit\" class=\"px-6 py-2.5 bg-sky-500 hover:bg-sky-600 text-white font-semibold rounded-xl text-sm shadow-lg shadow-sky-500/20\">Kaydet</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- Order Modal -->\n    <div id=\"modal-order\" class=\"fixed inset-0 z-50 hidden flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4 overflow-y-auto\">\n        <div class=\"glass-panel p-6 sm:p-8 rounded-2xl w-full max-w-2xl border border-slate-700 shadow-2xl my-8\">\n            <div class=\"flex items-center justify-between border-b border-slate-800 pb-4 mb-6\">\n                <h3 id=\"modal-order-title\" class=\"text-lg font-bold text-white flex items-center gap-2\">\n                    <i data-lucide=\"package-plus\" class=\"w-5 h-5 text-sky-400\"></i> Yeni Sipari\u015f Olu\u015ftur\n                </h3>\n                <button onclick=\"closeOrderModal()\" class=\"text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800\">\n                    <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\n                </button>\n            </div>\n\n            <form id=\"order-form\" onsubmit=\"handleOrderSubmit(event)\" class=\"space-y-4\">\n                <input type=\"hidden\" id=\"order-edit-id\">\n                \n                <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">\u00dcretilecek Tesis *</label>\n                        <select id=\"form-order-facility\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-semibold text-sky-400\">\n                            <!-- Dynamic facilities -->\n                        </select>\n                    </div>\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Sipari\u015f No *</label>\n                        <input type=\"text\" id=\"form-order-no\" required placeholder=\"\u00d6rn: SIP-2026-001\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">M\u00fc\u015fteri / Proje Ad\u0131 *</label>\n                        <input type=\"text\" id=\"form-order-customer\" required placeholder=\"M\u00fc\u015fteri Ad\u0131\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    </div>\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Kap\u0131 / Kanat Modeli *</label>\n                        <input type=\"text\" id=\"form-order-model\" required placeholder=\"\u00d6rn: WPC Kanat 90x205\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    </div>\n                </div>\n\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Sipari\u015f Adedi *</label>\n                        <input type=\"number\" id=\"form-order-qty\" min=\"1\" required placeholder=\"\u00d6rn: 250\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    </div>\n                    <div>\n                        <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Teslim Tarihi *</label>\n                        <input type=\"date\" id=\"form-order-delivery\" required class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    </div>\n                </div>\n\n                <!-- Stages Selection / Tags -->\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">\n                        \u00dcretim A\u015famalar\u0131 (S\u0131ras\u0131yla) *\n                    </label>\n                    <div class=\"text-[11px] text-slate-400 mb-2\">Bu sipari\u015fin ge\u00e7ece\u011fi a\u015famalar\u0131 se\u00e7in veya \u00f6zel a\u015fama ekleyin:</div>\n                    \n                    <!-- Quick Stage Chips -->\n                    <div class=\"flex flex-wrap gap-1.5 mb-3\" id=\"quick-stage-chips\">\n                        <button type=\"button\" onclick=\"addStageTag('Seren Kesim')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ Seren Kesim</button>\n                        <button type=\"button\" onclick=\"addStageTag('CNC Strafor')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ CNC Strafor</button>\n                        <button type=\"button\" onclick=\"addStageTag('Levha Vakum')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ Levha Vakum</button>\n                        <button type=\"button\" onclick=\"addStageTag('ETA (Dolumlu Seren)')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ ETA</button>\n                        <button type=\"button\" onclick=\"addStageTag('Homag')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ Homag</button>\n                        <button type=\"button\" onclick=\"addStageTag('Pres')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ Pres</button>\n                        <button type=\"button\" onclick=\"addStageTag('Paketleme')\" class=\"px-2.5 py-1 text-xs rounded-lg bg-slate-900 text-slate-300 hover:bg-sky-500/20 hover:text-sky-300 border border-slate-700 transition\">+ Paketleme</button>\n                    </div>\n\n                    <!-- Custom Stage Input & Tag Container -->\n                    <div class=\"flex gap-2 mb-2\">\n                        <input type=\"text\" id=\"custom-stage-input\" placeholder=\"\u00d6zel a\u015fama ad\u0131 yaz\u0131n ve Enter'a bas\u0131n...\" class=\"flex-1 px-3.5 py-2 rounded-xl border text-sm\">\n                        <button type=\"button\" onclick=\"addCustomStageTag()\" class=\"px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-semibold rounded-xl border border-slate-700\">Ekle</button>\n                    </div>\n\n                    <div id=\"selected-stages-container\" class=\"min-h-[48px] p-2.5 rounded-xl bg-slate-900/60 border border-slate-800 flex flex-wrap gap-2 items-center\">\n                        <span id=\"no-stages-hint\" class=\"text-xs text-slate-500\">Hen\u00fcz a\u015fama eklenmedi. Yukar\u0131dan se\u00e7in.</span>\n                    </div>\n                </div>\n\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Sipari\u015f Notlar\u0131</label>\n                    <textarea id=\"form-order-notes\" rows=\"2\" placeholder=\"\u00d6zel talepler, ambalaj detay\u0131 vb.\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\"></textarea>\n                </div>\n\n                <div class=\"flex items-center justify-end gap-3 pt-4 border-t border-slate-800\">\n                    <button type=\"button\" onclick=\"closeOrderModal()\" class=\"px-4 py-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 text-sm\">\u0130ptal</button>\n                    <button type=\"submit\" class=\"px-6 py-2.5 bg-sky-500 hover:bg-sky-600 text-white font-semibold rounded-xl text-sm shadow-lg shadow-sky-500/20\">Kaydet</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- Machine Modal -->\n    <div id=\"modal-machine\" class=\"fixed inset-0 z-50 hidden flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4\">\n        <div class=\"glass-panel p-6 sm:p-8 rounded-2xl w-full max-w-md border border-slate-700 shadow-2xl\">\n            <div class=\"flex items-center justify-between border-b border-slate-800 pb-4 mb-6\">\n                <h3 id=\"modal-machine-title\" class=\"text-lg font-bold text-white flex items-center gap-2\">\n                    <i data-lucide=\"cpu\" class=\"w-5 h-5 text-indigo-400\"></i> Yeni Makine Ekle\n                </h3>\n                <button onclick=\"closeMachineModal()\" class=\"text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800\">\n                    <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\n                </button>\n            </div>\n\n            <form id=\"machine-form\" onsubmit=\"handleMachineSubmit(event)\" class=\"space-y-4\">\n                <input type=\"hidden\" id=\"machine-edit-id\">\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Bulundu\u011fu Tesis *</label>\n                    <select id=\"form-machine-facility\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm font-semibold text-indigo-400\">\n                        <!-- Dynamic facilities -->\n                    </select>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Makine / Hat Ad\u0131 *</label>\n                    <input type=\"text\" id=\"form-machine-name\" required placeholder=\"\u00d6rn: Seren Kesim 1, Homag Ebatlama\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">A\u015fama / B\u00f6l\u00fcm *</label>\n                    <input type=\"text\" id=\"form-machine-stage\" required placeholder=\"\u00d6rn: Seren Kesim, Homag, Pres, Paketleme\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Kapasite (Adet / Saat)</label>\n                    <input type=\"number\" step=\"0.1\" id=\"form-machine-capacity\" placeholder=\"\u00d6rn: 30\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Notlar</label>\n                    <textarea id=\"form-machine-notes\" rows=\"2\" placeholder=\"Bak\u0131m aral\u0131\u011f\u0131, marka vb.\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\"></textarea>\n                </div>\n                <div class=\"flex items-center justify-end gap-3 pt-4 border-t border-slate-800\">\n                    <button type=\"button\" onclick=\"closeMachineModal()\" class=\"px-4 py-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 text-sm\">\u0130ptal</button>\n                    <button type=\"submit\" class=\"px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-xl text-sm shadow-lg shadow-indigo-600/20\">Kaydet</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- User Modal -->\n    <div id=\"modal-user\" class=\"fixed inset-0 z-50 hidden flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4\">\n        <div class=\"glass-panel p-6 sm:p-8 rounded-2xl w-full max-w-md border border-slate-700 shadow-2xl\">\n            <div class=\"flex items-center justify-between border-b border-slate-800 pb-4 mb-6\">\n                <h3 id=\"modal-user-title\" class=\"text-lg font-bold text-white flex items-center gap-2\">\n                    <i data-lucide=\"user-plus\" class=\"w-5 h-5 text-sky-400\"></i> Yeni Kullan\u0131c\u0131 Ekle\n                </h3>\n                <button onclick=\"closeUserModal()\" class=\"text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800\">\n                    <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\n                </button>\n            </div>\n\n            <form id=\"user-form\" onsubmit=\"handleUserSubmit(event)\" class=\"space-y-4\">\n                <input type=\"hidden\" id=\"user-edit-id\">\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Ad Soyad *</label>\n                    <input type=\"text\" id=\"form-user-name\" required placeholder=\"\u00d6rn: Ahmet Y\u0131lmaz\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Kullan\u0131c\u0131 Ad\u0131 *</label>\n                    <input type=\"text\" id=\"form-user-username\" required placeholder=\"\u00d6rn: ahmety\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">\u015eifre *</label>\n                    <input type=\"password\" id=\"form-user-password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                    <span id=\"user-pw-hint\" class=\"text-[11px] text-slate-500 hidden\">De\u011fi\u015ftirmek istemiyorsan\u0131z bo\u015f b\u0131rak\u0131n.</span>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5\">Rol *</label>\n                    <select id=\"form-user-role\" class=\"w-full px-3.5 py-2.5 rounded-xl border text-sm\">\n                        <option value=\"operator\">Operat\u00f6r</option>\n                        <option value=\"admin\">Y\u00f6netici (Admin)</option>\n                    </select>\n                </div>\n                <div class=\"flex items-center justify-end gap-3 pt-4 border-t border-slate-800\">\n                    <button type=\"button\" onclick=\"closeUserModal()\" class=\"px-4 py-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 text-sm\">\u0130ptal</button>\n                    <button type=\"submit\" class=\"px-6 py-2.5 bg-sky-500 hover:bg-sky-600 text-white font-semibold rounded-xl text-sm shadow-lg shadow-sky-500/20\">Kaydet</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- Application JavaScript Logic -->\n    <script>\n        // Global App State\n        let currentUser = null;\n        let allFacilities = [];\n        let allOrders = [];\n        let allMachines = [];\n        let allUsers = [];\n        let selectedOrderStagesTags = [];\n        let currentPeriod = 'weekly'; // daily, weekly, monthly\n        let currentFacilityFilter = 'all'; // all, fac1, fac2\n        let dailyActiveFacility = 'fac1';\n\n        // DOM Ready\n        document.addEventListener('DOMContentLoaded', () => {\n            lucide.createIcons();\n            \n            const now = new Date();\n            const todayStr = now.toISOString().split('T')[0];\n            const currentMonthStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;\n            \n            document.getElementById('daily-date-picker').value = todayStr;\n            document.getElementById('global-month-picker').value = currentMonthStr;\n\n            const storedUser = localStorage.getItem('kanat_user');\n            if (storedUser) {\n                try {\n                    currentUser = JSON.parse(storedUser);\n                    applyUserAuth();\n                } catch(e) {\n                    showLoginOverlay();\n                }\n            } else {\n                showLoginOverlay();\n            }\n\n            document.getElementById('custom-stage-input')?.addEventListener('keydown', (e) => {\n                if (e.key === 'Enter') {\n                    e.preventDefault();\n                    addCustomStageTag();\n                }\n            });\n        });\n\n        function showToast(message, type = 'success') {\n            const toast = document.getElementById('toast');\n            const content = document.getElementById('toast-content');\n            \n            if (type === 'success') {\n                content.className = 'flex items-center gap-3 px-5 py-3.5 rounded-xl shadow-2xl border text-sm font-medium bg-emerald-950/90 text-emerald-300 border-emerald-700/60';\n                content.innerHTML = `<i data-lucide=\"check-circle\" class=\"w-5 h-5 text-emerald-400\"></i> <span>${message}</span>`;\n            } else if (type === 'error') {\n                content.className = 'flex items-center gap-3 px-5 py-3.5 rounded-xl shadow-2xl border text-sm font-medium bg-rose-950/90 text-rose-300 border-rose-700/60';\n                content.innerHTML = `<i data-lucide=\"alert-circle\" class=\"w-5 h-5 text-rose-400\"></i> <span>${message}</span>`;\n            } else {\n                content.className = 'flex items-center gap-3 px-5 py-3.5 rounded-xl shadow-2xl border text-sm font-medium bg-sky-950/90 text-sky-300 border-sky-700/60';\n                content.innerHTML = `<i data-lucide=\"info\" class=\"w-5 h-5 text-sky-400\"></i> <span>${message}</span>`;\n            }\n            \n            lucide.createIcons();\n            toast.classList.remove('translate-y-20', 'opacity-0', 'pointer-events-none');\n            setTimeout(() => {\n                toast.classList.add('translate-y-20', 'opacity-0', 'pointer-events-none');\n            }, 3500);\n        }\n\n        function showLoginOverlay() {\n            document.getElementById('login-overlay').classList.remove('hidden');\n        }\n\n        function hideLoginOverlay() {\n            document.getElementById('login-overlay').classList.add('hidden');\n        }\n\n        async function handleLogin(e) {\n            e.preventDefault();\n            const u = document.getElementById('login-username').value.trim();\n            const p = document.getElementById('login-password').value;\n            const errBox = document.getElementById('login-error');\n            errBox.classList.add('hidden');\n\n            try {\n                const res = await fetch('/api/auth/login', {\n                    method: 'POST',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify({ username: u, password: p })\n                });\n                const data = await res.json();\n                if (!res.ok) {\n                    errBox.textContent = data.detail || 'Giri\u015f ba\u015far\u0131s\u0131z.';\n                    errBox.classList.remove('hidden');\n                    return;\n                }\n                currentUser = data.user;\n                localStorage.setItem('kanat_user', JSON.stringify(currentUser));\n                applyUserAuth();\n                hideLoginOverlay();\n                showToast(`Ho\u015f geldiniz, ${currentUser.name}!`);\n            } catch(err) {\n                errBox.textContent = 'Sunucuya ba\u011flan\u0131lamad\u0131.';\n                errBox.classList.remove('hidden');\n            }\n        }\n\n        function handleLogout() {\n            localStorage.removeItem('kanat_user');\n            currentUser = null;\n            location.reload();\n        }\n\n        function applyUserAuth() {\n            if (!currentUser) return;\n            document.getElementById('user-display-name').textContent = currentUser.name;\n\n            const userTabBtn = document.getElementById('tab-btn-users');\n            if (currentUser.role === 'admin') {\n                userTabBtn.classList.remove('hidden');\n            } else {\n                userTabBtn.classList.add('hidden');\n            }\n            hideLoginOverlay();\n\n            loadFacilities();\n            loadDashboard();\n            loadOrders();\n            loadMachines();\n            loadUsersList();\n            handleDailyDateChange();\n        }\n\n        function switchTab(tabId) {\n            ['dashboard', 'orders', 'daily', 'machines', 'users'].forEach(t => {\n                const sec = document.getElementById(`tab-${t}`);\n                const btn = document.getElementById(`tab-btn-${t}`);\n                if (sec && btn) {\n                    if (t === tabId) {\n                        sec.classList.remove('hidden');\n                        btn.classList.add('active');\n                    } else {\n                        sec.classList.add('hidden');\n                        btn.classList.remove('active');\n                    }\n                }\n            });\n\n            if (tabId === 'dashboard') loadDashboard();\n            if (tabId === 'orders') loadOrders();\n            if (tabId === 'machines') loadMachines();\n            if (tabId === 'users') loadUsersList();\n            if (tabId === 'daily') handleDailyDateChange();\n        }\n\n        // ==============================================================\n        // INSTANT FACILITY ORDER SWITCHING (CLICK -> DIRECT ORDERS)\n        // ==============================================================\n        function goToFacilityOrders(fid) {\n            selectFacility(fid);\n            switchTab('orders');\n        }\n\n        function selectFacility(fid) {\n            currentFacilityFilter = fid;\n            \n            // Sync main facility buttons\n            ['all', 'fac1', 'fac2'].forEach(x => {\n                const btn = document.getElementById(`fac-btn-${x}`);\n                if (btn) {\n                    if (x === fid) btn.classList.add('active');\n                    else btn.classList.remove('active');\n                }\n                const pill = document.getElementById(`order-pill-${x}`);\n                if (pill) {\n                    if (x === fid) pill.classList.add('active');\n                    else pill.classList.remove('active');\n                }\n            });\n\n            const fac1 = allFacilities.find(f => f.id === 'fac1') || { name: '\u00dcst Tesis' };\n            const fac2 = allFacilities.find(f => f.id === 'fac2') || { name: 'Alt Tesis' };\n\n            let label = 'T\u00fcm Tesisler (Konsolide Toplam)';\n            if (fid === 'fac1') label = `\ud83c\udfed ${fac1.name}`;\n            if (fid === 'fac2') label = `\ud83c\udfed ${fac2.name}`;\n            document.getElementById('dash-selected-facility-label').textContent = label;\n            document.getElementById('orders-subtitle-text').textContent = `${label} - Kay\u0131tl\u0131 Sipari\u015f Listesi`;\n\n            loadDashboard();\n            loadOrders();\n            loadMachines();\n        }\n\n        async function loadFacilities() {\n            try {\n                const res = await fetch('/api/facilities');\n                const data = await res.json();\n                allFacilities = data;\n                renderFacilityTexts();\n            } catch(e) {\n                console.error(\"Facilities load error:\", e);\n            }\n        }\n\n        function renderFacilityTexts() {\n            const fac1 = allFacilities.find(f => f.id === 'fac1') || { name: '\u00dcst Tesis (1. Fabrika)' };\n            const fac2 = allFacilities.find(f => f.id === 'fac2') || { name: 'Alt Tesis (2. Fabrika)' };\n\n            document.getElementById('fac1-main-btn-text').textContent = `\ud83c\udfed ${fac1.name.toUpperCase()} (207 Sipari\u015f)`;\n            document.getElementById('fac2-main-btn-text').textContent = `\ud83c\udfed ${fac2.name.toUpperCase()} (36 Sipari\u015f)`;\n            \n            document.getElementById('fac1-label-name').textContent = `${fac1.name} (207)`;\n            document.getElementById('fac2-label-name').textContent = `${fac2.name} (36)`;\n\n            document.getElementById('daily-fac1-text').textContent = `\ud83c\udfed ${fac1.name.toUpperCase()} (207 Sipari\u015f)`;\n            document.getElementById('daily-fac2-text').textContent = `\ud83c\udfed ${fac2.name.toUpperCase()} (36 Sipari\u015f)`;\n\n            // Order Modal Dropdown\n            const orderFac = document.getElementById('form-order-facility');\n            if (orderFac) {\n                orderFac.innerHTML = `\n                    <option value=\"fac1\">\ud83c\udfed ${fac1.name}</option>\n                    <option value=\"fac2\">\ud83c\udfed ${fac2.name}</option>\n                `;\n            }\n\n            // Machine Modal Dropdown\n            const mchFac = document.getElementById('form-machine-facility');\n            if (mchFac) {\n                mchFac.innerHTML = `\n                    <option value=\"fac1\">\ud83c\udfed ${fac1.name}</option>\n                    <option value=\"fac2\">\ud83c\udfed ${fac2.name}</option>\n                `;\n            }\n        }\n\n        function openFacilityModal() {\n            const fac1 = allFacilities.find(f => f.id === 'fac1') || { name: '\u00dcst Tesis (Ana Fabrika)' };\n            const fac2 = allFacilities.find(f => f.id === 'fac2') || { name: 'Alt Tesis (2. Fabrika)' };\n            document.getElementById('form-fac1-name').value = fac1.name;\n            document.getElementById('form-fac2-name').value = fac2.name;\n            document.getElementById('modal-facility').classList.remove('hidden');\n            lucide.createIcons();\n        }\n\n        function closeFacilityModal() {\n            document.getElementById('modal-facility').classList.add('hidden');\n        }\n\n        async function handleFacilitySubmit(e) {\n            e.preventDefault();\n            const n1 = document.getElementById('form-fac1-name').value.trim();\n            const n2 = document.getElementById('form-fac2-name').value.trim();\n\n            try {\n                await fetch('/api/facilities/fac1', {\n                    method: 'PUT',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify({ name: n1 })\n                });\n                await fetch('/api/facilities/fac2', {\n                    method: 'PUT',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify({ name: n2 })\n                });\n\n                showToast('Tesis isimleri g\u00fcncellendi!');\n                closeFacilityModal();\n                await loadFacilities();\n                selectFacility(currentFacilityFilter);\n            } catch(e) {\n                showToast('Tesis g\u00fcncelleme hatas\u0131.', 'error');\n            }\n        }\n\n        // ==============================================================\n        // PERIOD & MONTH SWITCHING\n        // ==============================================================\n        function setPeriod(p) {\n            currentPeriod = p;\n            ['daily', 'weekly', 'monthly'].forEach(x => {\n                const btn = document.getElementById(`period-btn-${x}`);\n                if (btn) {\n                    if (x === p) btn.classList.add('active');\n                    else btn.classList.remove('active');\n                }\n            });\n            loadDashboard();\n        }\n\n        function handleGlobalMonthChange() {\n            loadDashboard();\n        }\n\n        // ==============================================================\n        // DASHBOARD, KONSOL\u0130DE TOPLAM & SARKAN S\u0130PAR\u0130\u015eLER\n        // ==============================================================\n        async function loadDashboard() {\n            try {\n                const monthVal = document.getElementById('global-month-picker').value;\n                const targetDate = monthVal ? `${monthVal}-01` : null;\n                const url = `/api/dashboard?facility_id=${currentFacilityFilter}&period=${currentPeriod}&target_date=${targetDate || ''}`;\n                \n                const res = await fetch(url);\n                const data = await res.json();\n\n                // 1. Period Title & Consolidated Output\n                let periodTitle = 'Bu Hafta \u00c7\u0131kan Toplam Kap\u0131';\n                let periodOutput = data.weekly_summary?.total_output || 0;\n                let periodRange = `${data.weekly_summary?.start_date} \u2014 ${data.weekly_summary?.end_date}`;\n\n                if (currentPeriod === 'daily') {\n                    periodTitle = 'Bug\u00fcn \u00c7\u0131kan Toplam Kap\u0131';\n                    periodOutput = data.today_summary?.output || 0;\n                    periodRange = data.today_summary?.date;\n                } else if (currentPeriod === 'monthly') {\n                    periodTitle = `${data.monthly_summary?.month_name} Ay\u0131 \u00c7\u0131kan Toplam Kap\u0131`;\n                    periodOutput = data.monthly_summary?.total_output || 0;\n                    periodRange = `${data.monthly_summary?.start_date} \u2014 ${data.monthly_summary?.end_date}`;\n                }\n\n                if (currentFacilityFilter === 'fac1') {\n                    const fac1Name = allFacilities.find(f => f.id === 'fac1')?.name || '\u00dcst Tesis';\n                    periodTitle = `[${fac1Name}] ${periodTitle}`;\n                } else if (currentFacilityFilter === 'fac2') {\n                    const fac2Name = allFacilities.find(f => f.id === 'fac2')?.name || 'Alt Tesis';\n                    periodTitle = `[${fac2Name}] ${periodTitle}`;\n                }\n\n                document.getElementById('dash-period-title').textContent = periodTitle;\n                document.getElementById('dash-consolidated-total').innerHTML = `${periodOutput.toLocaleString('tr-TR')} <span class=\"text-base font-normal text-slate-400\">kap\u0131</span>`;\n                document.getElementById('dash-period-range').textContent = periodRange;\n                document.getElementById('dash-auto-month-label').textContent = data.monthly_summary?.month_name || '--';\n\n                // Facility Breakdown numbers\n                const fb1 = data.facility_breakdown?.fac1 || {};\n                const fb2 = data.facility_breakdown?.fac2 || {};\n                \n                let out1 = fb1.weekly_output || 0;\n                let out2 = fb2.weekly_output || 0;\n                if (currentPeriod === 'daily') {\n                    out1 = fb1.today_output || 0;\n                    out2 = fb2.today_output || 0;\n                } else if (currentPeriod === 'monthly') {\n                    out1 = fb1.monthly_output || 0;\n                    out2 = fb2.monthly_output || 0;\n                }\n\n                document.getElementById('dash-fac1-output').innerHTML = `${out1.toLocaleString('tr-TR')} <span class=\"text-xs font-normal text-slate-400\">kap\u0131</span>`;\n                document.getElementById('dash-fac2-output').innerHTML = `${out2.toLocaleString('tr-TR')} <span class=\"text-xs font-normal text-slate-400\">kap\u0131</span>`;\n\n                // 2. Sarkan ve Kritik Sipari\u015fler Tablosu\n                const sarkanTbody = document.getElementById('sarkan-siparisler-tbody');\n                const sarkanBadge = document.getElementById('sarkan-count-badge');\n                const sarkanList = data.sarkan_siparisler || [];\n                \n                sarkanBadge.textContent = `${sarkanList.length} Kritik / Sarkan Sipari\u015f`;\n                if (sarkanList.length === 0) {\n                    sarkanTbody.innerHTML = `<tr><td colspan=\"9\" class=\"text-center py-6 text-emerald-400 font-medium\">Harika! Se\u00e7ili tesiste sarkan sipari\u015f bulunmuyor. T\u00fcm teslimatlar zaman\u0131nda! \ud83c\udf89</td></tr>`;\n                } else {\n                    sarkanTbody.innerHTML = sarkanList.map(s => {\n                        let delayText = '';\n                        if (s.delay_days > 0) {\n                            delayText = `<span class=\"badge bg-rose-500/20 text-rose-300 border border-rose-500/40 font-bold animate-pulse\">\ud83d\udea8 ${s.delay_days} G\u00fcn Gecikti</span>`;\n                        } else if (s.days_left !== undefined) {\n                            delayText = `<span class=\"badge bg-amber-500/20 text-amber-300 border border-amber-500/40\">\u26a0\ufe0f ${s.days_left} G\u00fcn Kald\u0131</span>`;\n                        }\n\n                        return `\n                        <tr class=\"hover:bg-slate-900/60 transition\">\n                            <td class=\"px-4 py-3 font-bold text-white font-mono\">${s.order_no}</td>\n                            <td class=\"px-4 py-3 text-sky-400 font-semibold\">${s.facility_name || '-'}</td>\n                            <td class=\"px-4 py-3 font-medium text-slate-200\">${s.customer}</td>\n                            <td class=\"px-4 py-3 text-slate-300\">${s.model}</td>\n                            <td class=\"px-3 py-3 text-center font-bold text-white\">${s.qty}</td>\n                            <td class=\"px-3 py-3 text-center font-bold text-emerald-400\">${s.produced_qty}</td>\n                            <td class=\"px-3 py-3 text-center font-bold text-rose-400\">${s.remaining_qty}</td>\n                            <td class=\"px-3 py-3 text-center text-slate-400\">${s.delivery_date}</td>\n                            <td class=\"px-4 py-3 text-center\">${delayText}</td>\n                        </tr>\n                        `;\n                    }).join('');\n                }\n\n                // 3. Haftal\u0131k G\u00fcnl\u00fck Da\u011f\u0131l\u0131m Kartlar\u0131\n                const weeklyDaysContainer = document.getElementById('weekly-days-cards');\n                const weeklyDays = data.weekly_summary?.days || [];\n                document.getElementById('weekly-date-range').textContent = `Pazartesi (${data.weekly_summary?.start_date}) \u2014 Pazar (${data.weekly_summary?.end_date})`;\n\n                weeklyDaysContainer.innerHTML = weeklyDays.map(d => {\n                    const isToday = d.is_today;\n                    const borderClass = isToday ? 'border-sky-500/80 bg-sky-950/30' : 'border-slate-800 bg-slate-900/50';\n                    return `\n                    <div class=\"p-3.5 rounded-xl border ${borderClass} flex flex-col justify-between space-y-2 text-center\">\n                        <div class=\"text-xs font-semibold ${isToday ? 'text-sky-300' : 'text-slate-400'}\">${d.day_name}</div>\n                        <div class=\"text-xl font-bold ${d.output > 0 ? 'text-emerald-400' : 'text-slate-500'}\">${d.output} <span class=\"text-[10px] font-normal text-slate-400\">kap\u0131</span></div>\n                        ${isToday ? '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-sky-500/20 text-sky-400 font-bold uppercase\">Bug\u00fcn</span>' : '<span class=\"text-[9px] text-slate-600\">--</span>'}\n                    </div>\n                    `;\n                }).join('');\n\n                // 4. Render Active Orders Progress List\n                const ordersRes = await fetch(`/api/orders?facility_id=${currentFacilityFilter}`);\n                const orders = await ordersRes.json();\n                allOrders = orders;\n                const activeOrders = orders.filter(o => o.status === 'open');\n                const ordersContainer = document.getElementById('dash-orders-list');\n                \n                if (activeOrders.length === 0) {\n                    ordersContainer.innerHTML = `<div class=\"text-center py-6 text-slate-500 text-xs\">\u015eu anda a\u00e7\u0131k sipari\u015f bulunmuyor.</div>`;\n                } else {\n                    ordersContainer.innerHTML = activeOrders.slice(0, 15).map(o => {\n                        let delayBadge = '';\n                        if (o.days_remaining !== null) {\n                            if (o.days_remaining < 0) {\n                                delayBadge = `<span class=\"badge bg-rose-500/20 text-rose-300 border border-rose-500/40\">${Math.abs(o.days_remaining)} g\u00fcn gecikti</span>`;\n                            } else if (o.days_remaining <= 3) {\n                                delayBadge = `<span class=\"badge bg-amber-500/20 text-amber-300 border border-amber-500/40\">${o.days_remaining} g\u00fcn kald\u0131</span>`;\n                            } else {\n                                delayBadge = `<span class=\"badge bg-slate-800 text-slate-400\">${o.days_remaining} g\u00fcn kald\u0131</span>`;\n                            }\n                        }\n                        const facName = allFacilities.find(f => f.id === (o.facility_id || 'fac1'))?.name || 'Tesis';\n\n                        return `\n                        <div class=\"p-4 rounded-xl bg-slate-900/60 border border-slate-800/80 hover:border-slate-700 transition space-y-2\">\n                            <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-1\">\n                                <div class=\"flex items-center gap-2\">\n                                    <span class=\"font-bold text-white text-sm\">${o.order_no}</span>\n                                    <span class=\"text-[10px] px-2 py-0.5 rounded bg-sky-500/10 text-sky-400 border border-sky-500/20 font-semibold\">${facName}</span>\n                                    <span class=\"text-xs text-slate-400\">\u2022 ${o.customer}</span>\n                                    <span class=\"text-xs font-medium text-sky-400 font-mono\">[${o.model}]</span>\n                                </div>\n                                <div class=\"flex items-center gap-3 text-xs\">\n                                    <span class=\"text-slate-400\">${o.produced_qty || 0} / <strong>${o.qty} adet</strong> (Kalan: <strong class=\"text-rose-400\">${o.remaining_qty || 0}</strong>)</span>\n                                    ${delayBadge}\n                                </div>\n                            </div>\n                            <div class=\"w-full bg-slate-950 rounded-full h-2 overflow-hidden border border-slate-800\">\n                                <div class=\"bg-gradient-to-r from-sky-500 to-emerald-500 h-2 rounded-full transition-all duration-500\" style=\"width: ${Math.min(o.progress_pct, 100)}%\"></div>\n                            </div>\n                            <div class=\"flex justify-between text-[11px] text-slate-500\">\n                                <span>A\u015famalar: ${(o.stages || []).join(' \u2192 ')}</span>\n                                <span class=\"font-semibold text-slate-300\">%${o.progress_pct} tamamland\u0131</span>\n                            </div>\n                        </div>`;\n                    }).join('');\n                }\n\n                // 5. Render Stage Stats\n                const stageStatsContainer = document.getElementById('dash-stage-stats');\n                const sstats = data.stage_stats || [];\n                if (sstats.length === 0) {\n                    stageStatsContainer.innerHTML = `<div class=\"text-xs text-slate-500 py-4 text-center\">Hen\u00fcz a\u015fama \u00fcretim verisi bulunmuyor.</div>`;\n                } else {\n                    stageStatsContainer.innerHTML = sstats.map(s => `\n                        <div class=\"flex items-center justify-between p-2.5 rounded-lg bg-slate-900/50 border border-slate-800/60 text-xs\">\n                            <span class=\"font-medium text-slate-300\">${s.stage}</span>\n                            <span class=\"badge bg-sky-500/10 text-sky-400 border border-sky-500/20\">${s.output.toLocaleString('tr-TR')} adet</span>\n                        </div>\n                    `).join('');\n                }\n\n                // 6. Render Top Machines\n                const machineStatsContainer = document.getElementById('dash-machine-stats');\n                const mstats = data.machine_stats || [];\n                if (mstats.length === 0) {\n                    machineStatsContainer.innerHTML = `<div class=\"text-xs text-slate-500 py-4 text-center\">Hen\u00fcz makine \u00fcretim verisi bulunmuyor.</div>`;\n                } else {\n                    machineStatsContainer.innerHTML = mstats.map(m => `\n                        <div class=\"flex items-center justify-between p-2.5 rounded-lg bg-slate-900/50 border border-slate-800/60 text-xs\">\n                            <span class=\"font-medium text-slate-300\">${m.name}</span>\n                            <span class=\"badge bg-emerald-500/10 text-emerald-400 border border-emerald-500/20\">${m.output.toLocaleString('tr-TR')} adet</span>\n                        </div>\n                    `).join('');\n                }\n\n                lucide.createIcons();\n            } catch(err) {\n                console.error(\"Dashboard error:\", err);\n            }\n        }\n\n        // ==============================================================\n        // ORDERS LOGIC\n        // ==============================================================\n        async function loadOrders() {\n            try {\n                // Fetch ALL orders so we can calculate exact counts\n                const resAll = await fetch('/api/orders?facility_id=all');\n                const allO = await resAll.json();\n                \n                const cAll = allO.length;\n                const cFac1 = allO.filter(o => (o.facility_id || 'fac1') === 'fac1').length;\n                const cFac2 = allO.filter(o => (o.facility_id || 'fac1') === 'fac2').length;\n\n                document.getElementById('count-all-orders').textContent = cAll;\n                document.getElementById('count-fac1-orders').textContent = cFac1;\n                document.getElementById('count-fac2-orders').textContent = cFac2;\n\n                const res = await fetch(`/api/orders?facility_id=${currentFacilityFilter}`);\n                const orders = await res.json();\n                allOrders = orders;\n                renderOrdersTable(orders);\n                populateDailyOrderDropdown();\n            } catch(e) {\n                console.error(\"Orders load error:\", e);\n            }\n        }\n\n        function filterOrdersTableBySearch() {\n            const query = document.getElementById('order-search-input').value.toLowerCase().trim();\n            if (!query) {\n                renderOrdersTable(allOrders);\n                return;\n            }\n            const filtered = allOrders.filter(o => \n                (o.order_no || '').toLowerCase().includes(query) ||\n                (o.customer || '').toLowerCase().includes(query) ||\n                (o.model || '').toLowerCase().includes(query) ||\n                (o.notes || '').toLowerCase().includes(query)\n            );\n            renderOrdersTable(filtered);\n        }\n\n        function renderOrdersTable(orders) {\n            const tbody = document.getElementById('orders-table-body');\n            if (orders.length === 0) {\n                tbody.innerHTML = `<tr><td colspan=\"11\" class=\"text-center py-8 text-slate-500\">Se\u00e7ili tesiste kay\u0131tl\u0131 sipari\u015f bulunmuyor.</td></tr>`;\n                return;\n            }\n            tbody.innerHTML = orders.map(o => {\n                const isDone = o.status === 'done';\n                let statusBadge = isDone \n                    ? `<span class=\"badge bg-emerald-500/20 text-emerald-300 border border-emerald-500/40\">Tamamland\u0131</span>`\n                    : `<span class=\"badge bg-sky-500/20 text-sky-300 border border-sky-500/40\">A\u00e7\u0131k</span>`;\n\n                if (!isDone && o.days_remaining !== null && o.days_remaining < 0) {\n                    statusBadge = `<span class=\"badge bg-rose-500/20 text-rose-300 border border-rose-500/40\">\ud83d\udea8 Sarkt\u0131</span>`;\n                }\n\n                const isFac1 = (o.facility_id || 'fac1') === 'fac1';\n                const facName = allFacilities.find(f => f.id === (o.facility_id || 'fac1'))?.name || (isFac1 ? '\u00dcst Tesis' : 'Alt Tesis');\n                const facBadgeClass = isFac1 ? 'bg-sky-500/10 text-sky-400 border-sky-500/20' : 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';\n\n                return `\n                <tr class=\"hover:bg-slate-900/50 transition\">\n                    <td class=\"px-4 py-3.5 font-bold text-white font-mono\">${o.order_no}</td>\n                    <td class=\"px-4 py-3.5\"><span class=\"badge ${facBadgeClass} text-[11px] font-semibold\">${facName}</span></td>\n                    <td class=\"px-4 py-3.5 font-medium text-slate-200\">${o.customer}</td>\n                    <td class=\"px-4 py-3.5 text-slate-300 text-xs\">${o.model}</td>\n                    <td class=\"px-4 py-3.5 text-center font-bold text-white\">${o.qty}</td>\n                    <td class=\"px-4 py-3.5 text-center font-bold text-emerald-400\">${o.produced_qty || 0}</td>\n                    <td class=\"px-4 py-3.5 text-center font-bold text-rose-400\">${o.remaining_qty !== undefined ? o.remaining_qty : (o.qty - (o.produced_qty || 0))}</td>\n                    <td class=\"px-4 py-3.5 text-xs text-slate-400\">${o.delivery_date || '-'}</td>\n                    <td class=\"px-4 py-3.5 w-36\">\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"flex-1 bg-slate-950 rounded-full h-2 overflow-hidden border border-slate-800\">\n                                <div class=\"bg-gradient-to-r from-sky-500 to-emerald-500 h-2 rounded-full\" style=\"width: ${Math.min(o.progress_pct, 100)}%\"></div>\n                            </div>\n                            <span class=\"text-[11px] font-mono text-slate-300\">%${o.progress_pct}</span>\n                        </div>\n                    </td>\n                    <td class=\"px-4 py-3.5 text-center\">${statusBadge}</td>\n                    <td class=\"px-4 py-3.5 text-right space-x-1\">\n                        <button onclick=\"toggleOrderStatus('${o.id}', '${isDone ? 'open' : 'done'}')\" title=\"${isDone ? 'Sipari\u015fi Yeniden A\u00e7' : 'Tamamland\u0131 Olarak \u0130\u015faretle'}\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-emerald-400 transition\">\n                            <i data-lucide=\"${isDone ? 'rotate-ccw' : 'check'}\" class=\"w-4 h-4\"></i>\n                        </button>\n                        <button onclick=\"editOrder('${o.id}')\" title=\"D\u00fczenle\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-sky-400 transition\">\n                            <i data-lucide=\"edit-3\" class=\"w-4 h-4\"></i>\n                        </button>\n                        <button onclick=\"deleteOrder('${o.id}')\" title=\"Sil\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-rose-400 transition\">\n                            <i data-lucide=\"trash\" class=\"w-4 h-4\"></i>\n                        </button>\n                    </td>\n                </tr>\n                `;\n            }).join('');\n            lucide.createIcons();\n        }\n\n        function openOrderModal(isEdit = false) {\n            document.getElementById('modal-order-title').innerHTML = `<i data-lucide=\"${isEdit ? 'edit-3' : 'package-plus'}\" class=\"w-5 h-5 text-sky-400\"></i> ${isEdit ? 'Sipari\u015fi D\u00fczenle' : 'Yeni Sipari\u015f Olu\u015ftur'}`;\n            if (!isEdit) {\n                document.getElementById('order-form').reset();\n                document.getElementById('order-edit-id').value = '';\n                document.getElementById('form-order-facility').value = currentFacilityFilter !== 'all' ? currentFacilityFilter : 'fac1';\n                selectedOrderStagesTags = [\"Seren Kesim\", \"CNC Strafor\", \"Levha Vakum\", \"Pres\", \"Paketleme\"];\n                renderSelectedStagesTags();\n            }\n            document.getElementById('modal-order').classList.remove('hidden');\n            lucide.createIcons();\n        }\n\n        function closeOrderModal() {\n            document.getElementById('modal-order').classList.add('hidden');\n        }\n\n        function addStageTag(stageName) {\n            if (!selectedOrderStagesTags.includes(stageName)) {\n                selectedOrderStagesTags.push(stageName);\n                renderSelectedStagesTags();\n            }\n        }\n\n        function addCustomStageTag() {\n            const input = document.getElementById('custom-stage-input');\n            const val = input.value.trim();\n            if (val && !selectedOrderStagesTags.includes(val)) {\n                selectedOrderStagesTags.push(val);\n                input.value = '';\n                renderSelectedStagesTags();\n            }\n        }\n\n        function removeStageTag(idx) {\n            selectedOrderStagesTags.splice(idx, 1);\n            renderSelectedStagesTags();\n        }\n\n        function renderSelectedStagesTags() {\n            const container = document.getElementById('selected-stages-container');\n            if (selectedOrderStagesTags.length === 0) {\n                container.innerHTML = `<span class=\"text-xs text-slate-500\">Hen\u00fcz a\u015fama eklenmedi. Yukar\u0131dan se\u00e7in.</span>`;\n                return;\n            }\n            container.innerHTML = selectedOrderStagesTags.map((stg, i) => `\n                <span class=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-lg bg-sky-500/10 text-sky-300 border border-sky-500/30 text-xs font-semibold\">\n                    <span class=\"text-[10px] text-sky-500 font-mono\">${i+1}.</span>\n                    ${stg}\n                    <button type=\"button\" onclick=\"removeStageTag(${i})\" class=\"hover:text-rose-400 text-slate-400 p-0.5\">\n                        <i data-lucide=\"x\" class=\"w-3 h-3\"></i>\n                    </button>\n                </span>\n            `).join('');\n            lucide.createIcons();\n        }\n\n        async function handleOrderSubmit(e) {\n            e.preventDefault();\n            const editId = document.getElementById('order-edit-id').value;\n            const payload = {\n                order_no: document.getElementById('form-order-no').value.trim(),\n                facility_id: document.getElementById('form-order-facility').value,\n                customer: document.getElementById('form-order-customer').value.trim(),\n                model: document.getElementById('form-order-model').value.trim(),\n                qty: parseInt(document.getElementById('form-order-qty').value, 10),\n                delivery_date: document.getElementById('form-order-delivery').value,\n                stages: selectedOrderStagesTags,\n                notes: document.getElementById('form-order-notes').value.trim()\n            };\n\n            if (payload.stages.length === 0) {\n                showToast('L\u00fctfen en az bir \u00fcretim a\u015famas\u0131 se\u00e7iniz.', 'error');\n                return;\n            }\n\n            try {\n                let res;\n                if (editId) {\n                    res = await fetch(`/api/orders/${editId}`, {\n                        method: 'PUT',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                } else {\n                    res = await fetch('/api/orders', {\n                        method: 'POST',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                }\n\n                if (res.ok) {\n                    showToast(editId ? 'Sipari\u015f g\u00fcncellendi!' : 'Yeni sipari\u015f olu\u015fturuldu!');\n                    closeOrderModal();\n                    loadOrders();\n                    loadDashboard();\n                } else {\n                    const err = await res.json();\n                    showToast(err.detail || 'Kay\u0131t ba\u015far\u0131s\u0131z.', 'error');\n                }\n            } catch(e) {\n                showToast('Sunucu hatas\u0131.', 'error');\n            }\n        }\n\n        function editOrder(oid) {\n            const o = allOrders.find(x => x.id === oid);\n            if (!o) return;\n            document.getElementById('order-edit-id').value = o.id;\n            document.getElementById('form-order-facility').value = o.facility_id || 'fac1';\n            document.getElementById('form-order-no').value = o.order_no;\n            document.getElementById('form-order-customer').value = o.customer;\n            document.getElementById('form-order-model').value = o.model;\n            document.getElementById('form-order-qty').value = o.qty;\n            document.getElementById('form-order-delivery').value = o.delivery_date;\n            document.getElementById('form-order-notes').value = o.notes || '';\n            selectedOrderStagesTags = [...(o.stages || [])];\n            renderSelectedStagesTags();\n            openOrderModal(true);\n        }\n\n        async function toggleOrderStatus(oid, newStatus) {\n            try {\n                await fetch(`/api/orders/${oid}`, {\n                    method: 'PUT',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify({ status: newStatus })\n                });\n                showToast(`Sipari\u015f durumu g\u00fcncellendi: ${newStatus === 'done' ? 'Tamamland\u0131' : 'A\u00e7\u0131k'}`);\n                loadOrders();\n                loadDashboard();\n            } catch(e) {\n                showToast('Hata olu\u015ftu.', 'error');\n            }\n        }\n\n        async function deleteOrder(oid) {\n            if (!confirm('Bu sipari\u015fi silmek istedi\u011finize emin misiniz?')) return;\n            try {\n                const res = await fetch(`/api/orders/${oid}`, { method: 'DELETE' });\n                if (res.ok) {\n                    showToast('Sipari\u015f silindi.');\n                    loadOrders();\n                    loadDashboard();\n                }\n            } catch(e) {\n                showToast('Silme hatas\u0131.', 'error');\n            }\n        }\n\n        // ==============================================================\n        // DAILY PRODUCTION ENTRY LOGIC\n        // ==============================================================\n        function setDailyFacility(fid) {\n            dailyActiveFacility = fid;\n            \n            const btn1 = document.getElementById('daily-fac-btn-fac1');\n            const btn2 = document.getElementById('daily-fac-btn-fac2');\n            \n            if (fid === 'fac1') {\n                btn1.className = 'p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-sky-600 text-white border-sky-400 shadow-lg shadow-sky-600/30';\n                btn2.className = 'p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-slate-900 text-slate-400 border-slate-700 hover:border-slate-500';\n            } else {\n                btn2.className = 'p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-indigo-600 text-white border-indigo-400 shadow-lg shadow-indigo-600/30';\n                btn1.className = 'p-3.5 rounded-xl border text-sm font-bold flex items-center justify-center gap-2 transition bg-slate-900 text-slate-400 border-slate-700 hover:border-slate-500';\n            }\n\n            populateDailyOrderDropdown();\n            handleDailyDateChange();\n        }\n\n        async function populateDailyOrderDropdown() {\n            const select = document.getElementById('daily-order-select');\n            const res = await fetch(`/api/orders?facility_id=${dailyActiveFacility}`);\n            const orders = await res.json();\n            const active = orders.filter(o => o.status === 'open');\n            \n            const facName = allFacilities.find(f => f.id === dailyActiveFacility)?.name || 'Tesis';\n            select.innerHTML = `<option value=\"\">${facName} Sipari\u015fi Se\u00e7iniz (${active.length} A\u00e7\u0131k Sipari\u015f)...</option>` +\n                active.map(o => `<option value=\"${o.id}\">${o.order_no} - ${o.customer} (${o.model} - ${o.qty} adet)</option>`).join('');\n        }\n\n        async function handleDailyDateChange() {\n            const date = document.getElementById('daily-date-picker').value;\n            if (!date) return;\n\n            try {\n                const res = await fetch(`/api/daily/${date}`);\n                const dayData = await res.json();\n                \n                populateDailyOperatorDropdown();\n\n                const shift = document.getElementById('daily-shift-select').value;\n                const shiftEntries = (dayData.entries || []).filter(e => e.shift === shift && (e.facility_id || 'fac1') === dailyActiveFacility);\n\n                if (shiftEntries.length > 0) {\n                    if (shiftEntries[0].operator) {\n                        document.getElementById('daily-operator-select').value = shiftEntries[0].operator;\n                    }\n                    document.getElementById('daily-order-select').value = shiftEntries[0].order_id;\n                    renderStagesTableForOrder(shiftEntries[0].order_id, shiftEntries[0].stage_entries);\n                } else {\n                    const currentSelectedOrder = document.getElementById('daily-order-select').value;\n                    if (currentSelectedOrder) {\n                        renderStagesTableForOrder(currentSelectedOrder);\n                    } else {\n                        document.getElementById('daily-stages-tbody').innerHTML = `<tr><td colspan=\"5\" class=\"text-center py-8 text-slate-500 text-sm\">L\u00fctfen yukar\u0131dan bir sipari\u015f se\u00e7iniz.</td></tr>`;\n                    }\n                }\n\n                const facDowntimes = (dayData.downtimes || []).filter(d => (d.facility_id || 'fac1') === dailyActiveFacility);\n                renderDowntimesTable(facDowntimes);\n            } catch(e) {\n                console.error(\"Daily date change error:\", e);\n            }\n        }\n\n        function populateDailyOperatorDropdown() {\n            const select = document.getElementById('daily-operator-select');\n            const currentVal = select.value;\n            select.innerHTML = `<option value=\"\">Operat\u00f6r Se\u00e7in...</option>` +\n                allUsers.map(u => `<option value=\"${u.username}\">${u.name} (${u.role === 'admin' ? 'Y\u00f6netici' : 'Operat\u00f6r'})</option>`).join('');\n            if (currentVal) select.value = currentVal;\n        }\n\n        async function handleOrderSelectionForDaily() {\n            const orderId = document.getElementById('daily-order-select').value;\n            const badge = document.getElementById('selected-order-info-badge');\n            if (!orderId) {\n                badge.classList.add('hidden');\n                document.getElementById('daily-stages-tbody').innerHTML = `<tr><td colspan=\"5\" class=\"text-center py-8 text-slate-500 text-sm\">L\u00fctfen yukar\u0131dan bir sipari\u015f se\u00e7iniz.</td></tr>`;\n                return;\n            }\n            \n            try {\n                const res = await fetch(`/api/orders/${orderId}`);\n                const order = await res.json();\n                badge.classList.remove('hidden');\n                badge.innerHTML = `<strong>${order.model}</strong> \u2022 Hedef: <strong>${order.qty} adet</strong> \u2022 Tamamlanan: <strong class=\"text-emerald-400\">${order.produced_qty || 0}</strong> \u2022 Kalan: <strong class=\"text-rose-400\">${Math.max(0, order.qty - (order.produced_qty || 0))}</strong>`;\n                renderStagesTableForOrder(orderId, null, order);\n            } catch(e) {\n                console.error(\"Order info error:\", e);\n            }\n        }\n\n        async function renderStagesTableForOrder(orderId, savedStages = null, orderObj = null) {\n            let order = orderObj;\n            if (!order) {\n                const res = await fetch(`/api/orders/${orderId}`);\n                order = await res.json();\n            }\n            if (!order) return;\n\n            const stages = order.stages || [];\n            const tbody = document.getElementById('daily-stages-tbody');\n\n            const mres = await fetch(`/api/machines?facility_id=${dailyActiveFacility}`);\n            const facMachines = await mres.json();\n\n            tbody.innerHTML = stages.map((stg, idx) => {\n                const saved = savedStages ? savedStages.find(s => s.stage === stg) : null;\n                const outQty = saved ? saved.output_qty : 0;\n                const hours = saved ? saved.work_hours : 0;\n                const notes = saved ? saved.notes : '';\n\n                const machineOptions = `<option value=\"\">Makine / \u0130stasyon Se\u00e7in</option>` +\n                    facMachines.map(m => `<option value=\"${m.id}\" ${saved && saved.machine_id === m.id ? 'selected' : ''}>${m.name} (${m.stage})</option>`).join('');\n\n                return `\n                <tr class=\"stage-row\" data-stage=\"${stg}\">\n                    <td class=\"px-4 py-3 font-semibold text-white\">\n                        <div class=\"flex items-center gap-2\">\n                            <span class=\"w-5 h-5 rounded-full bg-sky-500/20 text-sky-400 text-xs flex items-center justify-center font-mono\">${idx+1}</span>\n                            <span>${stg}</span>\n                        </div>\n                    </td>\n                    <td class=\"px-4 py-3\">\n                        <select class=\"stage-machine-select w-full px-2.5 py-1.5 rounded-lg border text-xs\">\n                            ${machineOptions}\n                        </select>\n                    </td>\n                    <td class=\"px-3 py-3 text-center\">\n                        <input type=\"number\" min=\"0\" value=\"${outQty}\" class=\"stage-output-qty w-28 px-2.5 py-1 text-center rounded-lg border text-sm font-bold text-emerald-400\">\n                    </td>\n                    <td class=\"px-3 py-3 text-center\">\n                        <input type=\"number\" step=\"0.5\" min=\"0\" value=\"${hours}\" class=\"stage-hours w-24 px-2 py-1 text-center rounded-lg border text-xs\">\n                    </td>\n                    <td class=\"px-4 py-3\">\n                        <input type=\"text\" value=\"${notes || ''}\" placeholder=\"A\u00e7\u0131klama / Not\" class=\"stage-notes w-full px-2.5 py-1 rounded-lg border text-xs\">\n                    </td>\n                </tr>\n                `;\n            }).join('');\n        }\n\n        function renderDowntimesTable(downtimes) {\n            const tbody = document.getElementById('daily-downtimes-tbody');\n            if (downtimes.length === 0) {\n                tbody.innerHTML = `<tr><td colspan=\"5\" class=\"text-center py-4 text-slate-500 text-xs\">Duru\u015f kayd\u0131 bulunmuyor. Gerekirse 'Duru\u015f Ekle' butonuna basabilirsiniz.</td></tr>`;\n                return;\n            }\n            tbody.innerHTML = downtimes.map(dt => createDowntimeRowHtml(dt)).join('');\n            lucide.createIcons();\n        }\n\n        function addDowntimeRow() {\n            const tbody = document.getElementById('daily-downtimes-tbody');\n            if (tbody.innerHTML.includes('Duru\u015f kayd\u0131 bulunmuyor')) {\n                tbody.innerHTML = '';\n            }\n            tbody.insertAdjacentHTML('beforeend', createDowntimeRowHtml({ machine_id: '', reason: '', duration_min: 30, notes: '' }));\n            lucide.createIcons();\n        }\n\n        function createDowntimeRowHtml(dt) {\n            const facMachines = allMachines.filter(m => (m.facility_id || 'fac1') === dailyActiveFacility);\n            const machineOptions = `<option value=\"\">Makine Se\u00e7in</option>` +\n                facMachines.map(m => `<option value=\"${m.id}\" ${dt.machine_id === m.id ? 'selected' : ''}>${m.name}</option>`).join('');\n\n            return `\n            <tr class=\"downtime-row\">\n                <td class=\"px-4 py-2.5\">\n                    <select class=\"dt-machine w-full px-2 py-1 rounded-lg border text-xs\">${machineOptions}</select>\n                </td>\n                <td class=\"px-4 py-2.5\">\n                    <input type=\"text\" value=\"${dt.reason || ''}\" placeholder=\"\u00d6rn: B\u0131\u00e7ak de\u011fi\u015fimi, Motor ar\u0131zas\u0131\" class=\"dt-reason w-full px-2.5 py-1 rounded-lg border text-xs\">\n                </td>\n                <td class=\"px-3 py-2.5 text-center\">\n                    <input type=\"number\" min=\"0\" value=\"${dt.duration_min || 0}\" class=\"dt-duration w-24 px-2 py-1 text-center rounded-lg border text-xs\">\n                </td>\n                <td class=\"px-4 py-2.5\">\n                    <input type=\"text\" value=\"${dt.notes || ''}\" placeholder=\"Detay / Yap\u0131lan m\u00fcdahale\" class=\"dt-notes w-full px-2.5 py-1 rounded-lg border text-xs\">\n                </td>\n                <td class=\"px-3 py-2.5 text-right\">\n                    <button type=\"button\" onclick=\"this.closest('tr').remove()\" class=\"p-1 text-slate-400 hover:text-rose-400\"><i data-lucide=\"trash\" class=\"w-4 h-4\"></i></button>\n                </td>\n            </tr>\n            `;\n        }\n\n        async function saveDailyProduction() {\n            const date = document.getElementById('daily-date-picker').value;\n            const shift = document.getElementById('daily-shift-select').value;\n            const operator = document.getElementById('daily-operator-select').value;\n            const orderId = document.getElementById('daily-order-select').value;\n\n            if (!date) {\n                showToast('L\u00fctfen tarih se\u00e7iniz.', 'error');\n                return;\n            }\n\n            const stageRows = document.querySelectorAll('.stage-row');\n            const stageEntries = [];\n\n            stageRows.forEach(tr => {\n                const stage = tr.getAttribute('data-stage');\n                const machineId = tr.querySelector('.stage-machine-select').value;\n                const outQty = parseInt(tr.querySelector('.stage-output-qty').value, 10) || 0;\n                const hours = parseFloat(tr.querySelector('.stage-hours').value) || 0;\n                const notes = tr.querySelector('.stage-notes').value.trim();\n\n                stageEntries.push({\n                    stage: stage,\n                    machine_id: machineId,\n                    output_qty: outQty,\n                    work_hours: hours,\n                    notes: notes\n                });\n            });\n\n            const payload = {\n                date: date,\n                entries: orderId ? [{\n                    order_id: orderId,\n                    facility_id: dailyActiveFacility,\n                    shift: shift,\n                    operator: operator,\n                    stage_entries: stageEntries\n                }] : []\n            };\n\n            const dtRows = document.querySelectorAll('.downtime-row');\n            const downtimes = [];\n            dtRows.forEach(tr => {\n                downtimes.push({\n                    machine_id: tr.querySelector('.dt-machine').value,\n                    facility_id: dailyActiveFacility,\n                    stage: '',\n                    reason: tr.querySelector('.dt-reason').value.trim(),\n                    duration_min: parseFloat(tr.querySelector('.dt-duration').value) || 0,\n                    notes: tr.querySelector('.dt-notes').value.trim()\n                });\n            });\n\n            try {\n                const res1 = await fetch(`/api/daily/${date}`, {\n                    method: 'POST',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify(payload)\n                });\n\n                await fetch(`/api/daily/${date}/downtime`, {\n                    method: 'POST',\n                    headers: {'Content-Type': 'application/json'},\n                    body: JSON.stringify({ date: date, downtimes: downtimes })\n                });\n\n                if (res1.ok) {\n                    showToast('G\u00fcnl\u00fck \u00fcretim verileri ba\u015far\u0131yla kaydedildi!');\n                    loadDashboard();\n                    loadOrders();\n                } else {\n                    showToast('Kaydetme hatas\u0131 olu\u015ftu.', 'error');\n                }\n            } catch(e) {\n                showToast('Sunucu ba\u011flant\u0131 hatas\u0131.', 'error');\n            }\n        }\n\n        // ==============================================================\n        // MACHINES LOGIC\n        // ==============================================================\n        async function loadMachines() {\n            try {\n                const res = await fetch(`/api/machines?facility_id=${currentFacilityFilter}`);\n                const machines = await res.json();\n                allMachines = machines;\n                renderMachinesTable(machines);\n            } catch(e) {\n                console.error(\"Machines load error:\", e);\n            }\n        }\n\n        function renderMachinesTable(machines) {\n            const tbody = document.getElementById('machines-table-body');\n            if (machines.length === 0) {\n                tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center py-8 text-slate-500\">Se\u00e7ili tesiste tan\u0131ml\u0131 makine bulunmuyor.</td></tr>`;\n                return;\n            }\n            tbody.innerHTML = machines.map(m => {\n                let statusBadge = '<span class=\"badge bg-emerald-500/20 text-emerald-300 border border-emerald-500/40\">\ud83d\udfe2 Aktif</span>';\n                if (m.status === 'broken') statusBadge = '<span class=\"badge bg-rose-500/20 text-rose-300 border border-rose-500/40\">\ud83d\udd34 Ar\u0131zal\u0131</span>';\n                if (m.status === 'maintenance') statusBadge = '<span class=\"badge bg-amber-500/20 text-amber-300 border border-amber-500/40\">\ud83d\udfe1 Bak\u0131mda</span>';\n\n                const isFac1 = (m.facility_id || 'fac1') === 'fac1';\n                const facName = allFacilities.find(f => f.id === (m.facility_id || 'fac1'))?.name || (isFac1 ? '\u00dcst Tesis' : 'Alt Tesis');\n                const facBadgeClass = isFac1 ? 'bg-sky-500/10 text-sky-400 border-sky-500/20' : 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';\n\n                return `\n                <tr class=\"hover:bg-slate-900/50 transition\">\n                    <td class=\"px-4 py-3.5 font-bold text-white\">${m.name}</td>\n                    <td class=\"px-4 py-3.5\"><span class=\"badge ${facBadgeClass} text-[11px] font-semibold\">${facName}</span></td>\n                    <td class=\"px-4 py-3.5 text-indigo-300 font-medium\">${m.stage}</td>\n                    <td class=\"px-4 py-3.5 text-center font-mono\">${m.capacity_per_hour || 0}</td>\n                    <td class=\"px-4 py-3.5 text-center\">${statusBadge}</td>\n                    <td class=\"px-4 py-3.5 text-xs text-slate-400\">${m.notes || '-'}</td>\n                    <td class=\"px-4 py-3.5 text-right space-x-1\">\n                        <button onclick=\"editMachine('${m.id}')\" title=\"D\u00fczenle\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-indigo-400 transition\">\n                            <i data-lucide=\"edit-3\" class=\"w-4 h-4\"></i>\n                        </button>\n                        <button onclick=\"deleteMachine('${m.id}')\" title=\"Sil\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-rose-400 transition\">\n                            <i data-lucide=\"trash\" class=\"w-4 h-4\"></i>\n                        </button>\n                    </td>\n                </tr>\n                `;\n            }).join('');\n            lucide.createIcons();\n        }\n\n        function openMachineModal(isEdit = false) {\n            document.getElementById('modal-machine-title').innerHTML = `<i data-lucide=\"${isEdit ? 'edit-3' : 'cpu'}\" class=\"w-5 h-5 text-indigo-400\"></i> ${isEdit ? 'Makineyi D\u00fczenle' : 'Yeni Makine Ekle'}`;\n            if (!isEdit) {\n                document.getElementById('machine-form').reset();\n                document.getElementById('machine-edit-id').value = '';\n                document.getElementById('form-machine-facility').value = currentFacilityFilter !== 'all' ? currentFacilityFilter : 'fac1';\n            }\n            document.getElementById('modal-machine').classList.remove('hidden');\n            lucide.createIcons();\n        }\n\n        function closeMachineModal() {\n            document.getElementById('modal-machine').classList.add('hidden');\n        }\n\n        async function handleMachineSubmit(e) {\n            e.preventDefault();\n            const editId = document.getElementById('machine-edit-id').value;\n            const payload = {\n                name: document.getElementById('form-machine-name').value.trim(),\n                facility_id: document.getElementById('form-machine-facility').value,\n                stage: document.getElementById('form-machine-stage').value.trim(),\n                capacity_per_hour: parseFloat(document.getElementById('form-machine-capacity').value) || 0,\n                notes: document.getElementById('form-machine-notes').value.trim()\n            };\n\n            try {\n                let res;\n                if (editId) {\n                    res = await fetch(`/api/machines/${editId}`, {\n                        method: 'PUT',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                } else {\n                    res = await fetch('/api/machines', {\n                        method: 'POST',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                }\n\n                if (res.ok) {\n                    showToast(editId ? 'Makine g\u00fcncellendi!' : 'Yeni makine eklendi!');\n                    closeMachineModal();\n                    loadMachines();\n                } else {\n                    showToast('Kay\u0131t ba\u015far\u0131s\u0131z.', 'error');\n                }\n            } catch(e) {\n                showToast('Sunucu hatas\u0131.', 'error');\n            }\n        }\n\n        function editMachine(mid) {\n            const m = allMachines.find(x => x.id === mid);\n            if (!m) return;\n            document.getElementById('machine-edit-id').value = m.id;\n            document.getElementById('form-machine-facility').value = m.facility_id || 'fac1';\n            document.getElementById('form-machine-name').value = m.name;\n            document.getElementById('form-machine-stage').value = m.stage;\n            document.getElementById('form-machine-capacity').value = m.capacity_per_hour || 0;\n            document.getElementById('form-machine-notes').value = m.notes || '';\n            openMachineModal(true);\n        }\n\n        async function deleteMachine(mid) {\n            if (!confirm('Bu makineyi silmek istedi\u011finize emin misiniz?')) return;\n            try {\n                const res = await fetch(`/api/machines/${mid}`, { method: 'DELETE' });\n                if (res.ok) {\n                    showToast('Makine silindi.');\n                    loadMachines();\n                }\n            } catch(e) {\n                showToast('Silme hatas\u0131.', 'error');\n            }\n        }\n\n        // ==============================================================\n        // USERS MANAGEMENT LOGIC\n        // ==============================================================\n        async function loadUsersList() {\n            try {\n                const res = await fetch('/api/users');\n                const users = await res.json();\n                allUsers = users;\n                renderUsersTable(users);\n                populateDailyOperatorDropdown();\n            } catch(e) {\n                console.error(\"Users load error:\", e);\n            }\n        }\n\n        function renderUsersTable(users) {\n            const tbody = document.getElementById('users-table-body');\n            tbody.innerHTML = users.map(u => {\n                const isSuper = u.id === 'u1';\n                const roleBadge = u.role === 'admin' \n                    ? `<span class=\"badge bg-sky-500/20 text-sky-300 border border-sky-500/40\">Y\u00f6netici</span>`\n                    : `<span class=\"badge bg-slate-800 text-slate-400\">Operat\u00f6r</span>`;\n\n                return `\n                <tr class=\"hover:bg-slate-900/50 transition\">\n                    <td class=\"px-4 py-3.5 font-bold text-white\">${u.name}</td>\n                    <td class=\"px-4 py-3.5 font-mono text-slate-300\">${u.username}</td>\n                    <td class=\"px-4 py-3.5 text-center\">${roleBadge}</td>\n                    <td class=\"px-4 py-3.5 text-right space-x-1\">\n                        <button onclick=\"editUser('${u.id}')\" title=\"D\u00fczenle / \u015eifre De\u011fi\u015ftir\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-sky-400 transition\">\n                            <i data-lucide=\"edit-3\" class=\"w-4 h-4\"></i>\n                        </button>\n                        ${!isSuper ? `\n                        <button onclick=\"deleteUser('${u.id}')\" title=\"Sil\" class=\"p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-rose-400 transition\">\n                            <i data-lucide=\"trash\" class=\"w-4 h-4\"></i>\n                        </button>\n                        ` : ''}\n                    </td>\n                </tr>\n                `;\n            }).join('');\n            lucide.createIcons();\n        }\n\n        function openUserModal(isEdit = false) {\n            document.getElementById('modal-user-title').innerHTML = `<i data-lucide=\"${isEdit ? 'edit-3' : 'user-plus'}\" class=\"w-5 h-5 text-sky-400\"></i> ${isEdit ? 'Kullan\u0131c\u0131y\u0131 D\u00fczenle' : 'Yeni Kullan\u0131c\u0131 Ekle'}`;\n            const pwHint = document.getElementById('user-pw-hint');\n            const pwInput = document.getElementById('form-user-password');\n            const unInput = document.getElementById('form-user-username');\n\n            if (isEdit) {\n                pwHint.classList.remove('hidden');\n                pwInput.removeAttribute('required');\n                unInput.setAttribute('disabled', 'disabled');\n            } else {\n                document.getElementById('user-form').reset();\n                document.getElementById('user-edit-id').value = '';\n                pwHint.classList.add('hidden');\n                pwInput.setAttribute('required', 'required');\n                unInput.removeAttribute('disabled');\n            }\n            document.getElementById('modal-user').classList.remove('hidden');\n            lucide.createIcons();\n        }\n\n        function closeUserModal() {\n            document.getElementById('modal-user').classList.add('hidden');\n        }\n\n        async function handleUserSubmit(e) {\n            e.preventDefault();\n            const editId = document.getElementById('user-edit-id').value;\n            const pw = document.getElementById('form-user-password').value;\n\n            try {\n                let res;\n                if (editId) {\n                    const payload = {\n                        name: document.getElementById('form-user-name').value.trim(),\n                        role: document.getElementById('form-user-role').value\n                    };\n                    if (pw) payload.password = pw;\n\n                    res = await fetch(`/api/users/${editId}`, {\n                        method: 'PUT',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                } else {\n                    const payload = {\n                        name: document.getElementById('form-user-name').value.trim(),\n                        username: document.getElementById('form-user-username').value.trim(),\n                        password: pw,\n                        role: document.getElementById('form-user-role').value\n                    };\n                    res = await fetch('/api/users', {\n                        method: 'POST',\n                        headers: {'Content-Type': 'application/json'},\n                        body: JSON.stringify(payload)\n                    });\n                }\n\n                if (res.ok) {\n                    showToast(editId ? 'Kullan\u0131c\u0131 g\u00fcncellendi!' : 'Yeni kullan\u0131c\u0131 eklendi!');\n                    closeUserModal();\n                    loadUsersList();\n                } else {\n                    const err = await res.json();\n                    showToast(err.detail || 'Kullan\u0131c\u0131 i\u015flemi ba\u015far\u0131s\u0131z.', 'error');\n                }\n            } catch(e) {\n                showToast('Sunucu hatas\u0131.', 'error');\n            }\n        }\n\n        function editUser(uid) {\n            const u = allUsers.find(x => x.id === uid);\n            if (!u) return;\n            document.getElementById('user-edit-id').value = u.id;\n            document.getElementById('form-user-name').value = u.name;\n            document.getElementById('form-user-username').value = u.username;\n            document.getElementById('form-user-password').value = '';\n            document.getElementById('form-user-role').value = u.role;\n            openUserModal(true);\n        }\n\n        async function deleteUser(uid) {\n            if (!confirm('Bu kullan\u0131c\u0131y\u0131 silmek istedi\u011finize emin misiniz?')) return;\n            try {\n                const res = await fetch(`/api/users/${uid}`, { method: 'DELETE' });\n                if (res.ok) {\n                    showToast('Kullan\u0131c\u0131 silindi.');\n                    loadUsersList();\n                } else {\n                    const err = await res.json();\n                    showToast(err.detail || 'Silinemedi.', 'error');\n                }\n            } catch(e) {\n                showToast('Silme hatas\u0131.', 'error');\n            }\n        }\n    </script>\n</body>\n</html>\n"
